export const MIGRATIONS = [
  { name: "0001_init.sql", sql: `-- Users: one row per account.
-- password_hash format: "pbkdf2$<iters>$<salt_b64>$<hash_b64>"
CREATE TABLE users (
  id          TEXT PRIMARY KEY,
  email       TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  last_login_at INTEGER
);

CREATE INDEX idx_users_email ON users(LOWER(email));

-- Sessions: opaque token -> user. Token is the cookie value (random 32 bytes, base64url).
CREATE TABLE sessions (
  token       TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL,
  user_agent  TEXT
);

CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
` },
  { name: "0002_rooms.sql", sql: `-- Rooms: a lobby record for each game session. The live state lives in a Durable Object
-- keyed by room.id; this table is the index for discovery / cross-user queries.
CREATE TABLE rooms (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  host_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status      TEXT NOT NULL DEFAULT 'lobby',  -- 'lobby' | 'in_progress' | 'closed'
  max_players INTEGER NOT NULL DEFAULT 4,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);

CREATE INDEX idx_rooms_status ON rooms(status, updated_at DESC);

-- Memberships: who has joined which room. The DO is the source of truth for who's
-- currently connected; this table records the intent ("I have a seat in this room").
CREATE TABLE room_members (
  room_id   TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  joined_at INTEGER NOT NULL,
  PRIMARY KEY (room_id, user_id)
);

CREATE INDEX idx_members_user ON room_members(user_id);
` },
  { name: "0003_game_state.sql", sql: `-- ============================================================================
-- Orbital — Game State Schema (v1, alpha-target)
-- ============================================================================
--
-- This migration adds the per-match game state on top of the existing
-- accounts (0001) and lobby/room (0002) layers. It targets the asynchronous
-- daily-tick strategy game described in design doc v0.3.
--
-- KEY MODELING DECISIONS (read first):
--
--   1. Room vs. game. A \`rooms\` row (from 0002) is a lobby seat plan; when
--      the host starts the match, a \`games\` row is created with id == room id.
--      The room continues to exist so the lobby can show finished matches
--      and so post-game chronicle viewing has a stable join target.
--
--   2. Game-room as the tenancy boundary. Every gameplay row carries
--      \`game_id\` and almost every query is scoped by it. The \`Room\` Durable
--      Object owns the live working copy of state and writes through to D1
--      on tick commit; D1 is the source of truth for everything that
--      survives DO eviction.
--
--   3. Factions are first-class. A player joins a game by claiming exactly
--      one faction (1:1 user<->faction within a game). A faction can also be
--      AI-controlled (user_id NULL) or vacated/eliminated. Faction id is
--      the identity used by every other gameplay row (ownership, treaties,
--      senate votes, message authorship). Do NOT key gameplay rows on
--      user_id directly — that breaks AI/observer cases.
--
--   4. Per-game bodies. Bodies are not global seed data. They are copied
--      into \`game_bodies\` at game start so variant maps are possible and
--      so per-game state (ownership, development, resources) lives on the
--      same row that defines orbital geometry.
--
--   5. Keplerian orbits. Both bodies and ships store orbits as classical
--      elements (rp, ra, omega, M0, epoch, direction). This matches the
--      current prototype's patched-conics sim. If the engine ever moves to
--      RK4 N-body, add \`state_vector_*\` columns rather than restructuring.
--
--   6. Sensor visibility as stored projection. \`sensor_coverage\` materializes
--      "faction F can see body B at level L" so reads of bodies/ships can
--      be filtered with a single join. The tick processor recomputes this
--      table at the end of each tick.
--
--   7. Per-tick snapshots. \`game_snapshots\` stores a JSON dump of derived
--      state per tick for rollback and for the chronicle viewer. Authoritative
--      *live* state is the relational tables, not the snapshot blob.
--
--   8. Order intent. Most "orders" are state mutations directly visible on
--      domain rows (e.g. node.committed = 1, faction.research_queue, ship
--      build queue rows). The generic \`pending_orders\` table is for
--      cross-cutting actions that don't fit a single domain table
--      (e.g. sigint scans, signed declarations queued for tick boundary).
--
--   9. Reserved-for-v2 tables. \`standing_orders\` is defined here even
--      though v1 alpha won't implement the if-then engine, so the v2
--      migration is additive (no rename/restructure). Similarly,
--      \`messages.claimed_sender_faction_id\` is reserved so the v2 forgery
--      mechanic doesn't require a column rename.
--
--   10. Time. The unit of game time is \`tick_number\` (0-indexed). Wall-clock
--       timestamps are stored as INTEGER ms since epoch. Never confuse the
--       two: gameplay logic operates in ticks; the scheduler operates in ms.
--
-- ============================================================================
-- SECTION 1 — Games, ticks, factions, players
-- ============================================================================

-- One row per started match. The room (0002) is the lobby; a game is the
-- match itself. game.id == room.id so post-game viewing can join either way.
CREATE TABLE games (
  id                  TEXT PRIMARY KEY REFERENCES rooms(id) ON DELETE CASCADE,
  status              TEXT NOT NULL DEFAULT 'setup',
    -- 'setup'      : host is configuring map/factions, lobby open
    -- 'active'     : ticks are running
    -- 'completed'  : a victory condition triggered; chronicle finalized
    -- 'abandoned'  : host or system ended without a victor
  victory_type        TEXT,                -- NULL until completed; 'hegemony'|'political'|'last_standing'|'secret'|'abandoned'
  winner_faction_id   TEXT,                -- FK declared below (circular; enforced via trigger if needed)
  map_seed            TEXT NOT NULL,       -- deterministic body-generation seed; allows reproducibility
  current_tick        INTEGER NOT NULL DEFAULT 0,
  -- Match length and cadence. The schema defaults below are historical
  -- (the 0003 migration shipped with a 42-tick / 24h-per-tick "one move
  -- per day" design); the live defaults are now supplied explicitly by
  -- worker/lobby.js (DEFAULT_TOTAL_TICK_TARGET=4000,
  -- DEFAULT_TICK_INTERVAL_MS=450_000) so every newly-created match uses
  -- the current pace: 7.5 min/tick × 4000 ticks ≈ a 21-day game with
  -- Earth→Jupiter transits ≈ 1.5 real days. See DESIGN.md "Time and
  -- pacing" for the rationale.
  total_tick_target   INTEGER NOT NULL DEFAULT 4000,     -- design pace: 3-week match
  tick_interval_ms    INTEGER NOT NULL DEFAULT 450000,   -- 7.5 min/tick; lobby.js may override
  next_tick_at        INTEGER,             -- scheduled wall-clock ms; NULL while paused/setup
  senate_period_ticks INTEGER NOT NULL DEFAULT 7,
  created_at          INTEGER NOT NULL,
  started_at          INTEGER,
  completed_at        INTEGER
);

CREATE INDEX idx_games_status_next ON games(status, next_tick_at);

-- Tick log. One row per executed (or scheduled) tick. The tick processor
-- inserts a row with status='scheduled', flips it to 'processing' while
-- running, and 'completed' on success. Provides a join target for events.
CREATE TABLE game_ticks (
  game_id        TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  tick_number    INTEGER NOT NULL,
  status         TEXT NOT NULL DEFAULT 'scheduled',  -- 'scheduled'|'processing'|'completed'|'failed'
  scheduled_at   INTEGER NOT NULL,
  started_at     INTEGER,
  completed_at   INTEGER,
  error          TEXT,
  PRIMARY KEY (game_id, tick_number)
);

CREATE INDEX idx_ticks_schedule ON game_ticks(status, scheduled_at);

-- A faction is a seat in a specific game. Bound to a user (or AI) and a
-- capital body (loss-of-capital = elimination per design). The four
-- resource columns are the per-faction stockpile.
CREATE TABLE game_factions (
  id                 TEXT PRIMARY KEY,
  game_id            TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  user_id            TEXT REFERENCES users(id) ON DELETE SET NULL,  -- NULL = AI or vacated seat
  slot              INTEGER NOT NULL,            -- 0..N-1, stable seat number for UI ordering
  name              TEXT NOT NULL,               -- in-game faction name (e.g. "Verdan Concord")
  color             TEXT NOT NULL,               -- hex; used by renderer + chronicle
  status            TEXT NOT NULL DEFAULT 'active',  -- 'active'|'eliminated'|'observer'|'vacated'
  capital_body_id   TEXT,                        -- FK to game_bodies(id); set at game start
  reputation        INTEGER NOT NULL DEFAULT 0,
  senate_weight     INTEGER NOT NULL DEFAULT 1,  -- recomputed each tick; observers = 0.5 (stored *2 if needed)
  metal             INTEGER NOT NULL DEFAULT 0,
  fuel              INTEGER NOT NULL DEFAULT 0,
  gold              INTEGER NOT NULL DEFAULT 0,
  science           INTEGER NOT NULL DEFAULT 0,
  research_tech_id  TEXT,                        -- currently-researching tech; NULL = idle
  research_progress INTEGER NOT NULL DEFAULT 0,  -- science accumulated toward research_tech_id
  joined_at         INTEGER NOT NULL,
  eliminated_at_tick INTEGER,
  UNIQUE (game_id, slot),
  UNIQUE (game_id, user_id)                      -- a user can only hold one seat per game
);

CREATE INDEX idx_factions_game ON game_factions(game_id);
CREATE INDEX idx_factions_user ON game_factions(user_id);

-- ============================================================================
-- SECTION 2 — Bodies (per-game) and ownership
-- ============================================================================

-- Bodies are per-game so variant maps and dynamic per-body state share a row.
-- Geometry columns mirror the prototype's BODIES[] entries. Resource yield
-- columns are the per-tick production from this body when developed.
CREATE TABLE game_bodies (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  template_id     TEXT NOT NULL,            -- references seed catalog in code (e.g. 'sol','inara'); not a FK
  name            TEXT NOT NULL,
  type            TEXT NOT NULL,            -- 'star'|'terrestrial'|'gas-giant'|'moon'|'asteroid'|'lagrange'
  parent_body_id  TEXT REFERENCES game_bodies(id),   -- NULL for the system primary
  radius          REAL NOT NULL,            -- physical radius (sim units)
  soi             REAL,                     -- sphere of influence radius; NULL for the star
  mu              REAL NOT NULL,            -- gravitational parameter
  orbit_radius    REAL,                     -- semi-major axis around parent
  orbit_period    REAL,                     -- ticks or sim-time-units; defined by engine convention
  angle0          REAL,                     -- mean anomaly at epoch 0
  color           TEXT NOT NULL,
  -- per-tick base resource yield when fully developed (level 3); scaled by development_level
  yield_metal     INTEGER NOT NULL DEFAULT 0,
  yield_fuel      INTEGER NOT NULL DEFAULT 0,
  yield_gold      INTEGER NOT NULL DEFAULT 0,
  yield_science   INTEGER NOT NULL DEFAULT 0,
  -- per-game mutable state
  owner_faction_id    TEXT REFERENCES game_factions(id) ON DELETE SET NULL,
  development_level   INTEGER NOT NULL DEFAULT 0,    -- 0=unclaimed,1=claimed flag,2=outpost,3=developed base
  fortification_level INTEGER NOT NULL DEFAULT 0,
  shipyard_level      INTEGER NOT NULL DEFAULT 0,
  claimed_at_tick     INTEGER,
  developed_at_tick   INTEGER
);

CREATE INDEX idx_bodies_game ON game_bodies(game_id);
CREATE INDEX idx_bodies_owner ON game_bodies(owner_faction_id);
CREATE INDEX idx_bodies_parent ON game_bodies(parent_body_id);

-- Now that game_bodies exists, declare the deferred faction->capital FK
-- as an index-only contract (SQLite does not support late ADD CONSTRAINT;
-- the relationship is enforced in application code).
CREATE INDEX idx_factions_capital ON game_factions(capital_body_id);

-- Build queue on a body's shipyard. One row per ordered ship; consumed when
-- the tick processor completes construction.
CREATE TABLE game_body_build_queue (
  id                  TEXT PRIMARY KEY,
  game_id             TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  body_id             TEXT NOT NULL REFERENCES game_bodies(id) ON DELETE CASCADE,
  faction_id          TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  ship_class          TEXT NOT NULL,        -- 'frigate'|'cruiser'|'capital'|'stealth'
  queued_at_tick      INTEGER NOT NULL,
  completes_at_tick   INTEGER NOT NULL,
  cancelled_at_tick   INTEGER
);

CREATE INDEX idx_build_queue_completion ON game_body_build_queue(game_id, completes_at_tick)
  WHERE cancelled_at_tick IS NULL;

-- Body development queue (claim -> outpost -> developed). Similar shape;
-- separate table because development is independent of ship construction.
CREATE TABLE game_body_development (
  id                  TEXT PRIMARY KEY,
  game_id             TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  body_id             TEXT NOT NULL REFERENCES game_bodies(id) ON DELETE CASCADE,
  faction_id          TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  target_level        INTEGER NOT NULL,     -- 1, 2, or 3
  started_at_tick     INTEGER NOT NULL,
  completes_at_tick   INTEGER NOT NULL,
  cancelled_at_tick   INTEGER
);

CREATE INDEX idx_development_completion ON game_body_development(game_id, completes_at_tick)
  WHERE cancelled_at_tick IS NULL;

-- ============================================================================
-- SECTION 3 — Ships and maneuver nodes
-- ============================================================================

-- A ship lives in a parent body's SOI with a Keplerian orbit around it.
-- Orbits change discretely on burns; between burns the engine integrates
-- the analytical Kepler orbit.
CREATE TABLE game_ships (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  owner_faction_id TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  ship_class      TEXT NOT NULL,            -- 'frigate'|'cruiser'|'capital'|'stealth'
  parent_body_id  TEXT NOT NULL REFERENCES game_bodies(id) ON DELETE CASCADE,
  -- current orbit (around parent_body_id); updated whenever a node executes
  orbit_rp        REAL NOT NULL,
  orbit_ra        REAL NOT NULL,
  orbit_omega     REAL NOT NULL,            -- argument of periapsis (rad)
  orbit_m0        REAL NOT NULL,            -- mean anomaly at epoch
  orbit_epoch     REAL NOT NULL,            -- sim time at which m0 applies
  orbit_direction INTEGER NOT NULL DEFAULT 1, -- +1 prograde, -1 retrograde
  -- resources
  fuel            REAL NOT NULL,
  fuel_max        REAL NOT NULL,
  -- status
  status          TEXT NOT NULL DEFAULT 'active',  -- 'active'|'destroyed'|'mothballed'
  built_at_tick   INTEGER NOT NULL,
  destroyed_at_tick INTEGER
);

CREATE INDEX idx_ships_game ON game_ships(game_id);
CREATE INDEX idx_ships_owner ON game_ships(owner_faction_id);
CREATE INDEX idx_ships_parent ON game_ships(parent_body_id);

-- Maneuver nodes — the planned/committed/executed lifecycle for ship burns.
-- The renderer in the prototype already understands this exact shape.
CREATE TABLE game_ship_nodes (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  ship_id         TEXT NOT NULL REFERENCES game_ships(id) ON DELETE CASCADE,
  sequence        INTEGER NOT NULL,         -- ordering within the ship's plan; 0,1,2...
  anchor_kind     TEXT NOT NULL,            -- 'periapsis'|'apoapsis'|'encounter'|'capture'|'exit'|'absolute'
  anchor_body_id  TEXT REFERENCES game_bodies(id),   -- the body the anchor is relative to, if applicable
  target_body_id  TEXT REFERENCES game_bodies(id),   -- destination body for transfer/capture nodes
  scheduled_t     REAL NOT NULL,            -- sim time at which the burn fires
  dv_prograde     REAL NOT NULL DEFAULT 0,
  dv_normal       REAL NOT NULL DEFAULT 0,
  dv_radial       REAL NOT NULL DEFAULT 0,
  fuel_cost       REAL NOT NULL,            -- precomputed; the source of truth for fuel accounting at execute
  status          TEXT NOT NULL DEFAULT 'planned', -- 'planned'|'committed'|'executed'|'cancelled'|'failed'
  committed_at_tick INTEGER,
  executed_at_tick  INTEGER,
  UNIQUE (ship_id, sequence)
);

CREATE INDEX idx_nodes_ship ON game_ship_nodes(ship_id, sequence);
CREATE INDEX idx_nodes_due  ON game_ship_nodes(game_id, status, scheduled_t);

-- ============================================================================
-- SECTION 4 — Sensors, visibility, intelligence
-- ============================================================================

-- Per-faction view of bodies. Recomputed by the tick processor. The renderer
-- joins ships/bodies to this for fog-of-war. Coverage levels:
--   0 = unknown          (faction has no info; body invisible in UI)
--   1 = ephemeris        (orbit known, no current ship traffic visible)
--   2 = patrol           (ships in this SOI visible; trajectories shown)
--   3 = full intel       (build queue + development visible too)
CREATE TABLE sensor_coverage (
  game_id     TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  body_id     TEXT NOT NULL REFERENCES game_bodies(id) ON DELETE CASCADE,
  level       INTEGER NOT NULL,
  updated_at_tick INTEGER NOT NULL,
  PRIMARY KEY (game_id, faction_id, body_id)
);

CREATE INDEX idx_sensor_faction ON sensor_coverage(faction_id, body_id);

-- Sigint records — generated when sensors detect *that* a message was sent,
-- without revealing content. v2 may extend with partial-decrypt fields.
CREATE TABLE sigint_events (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  observer_faction_id TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  detected_at_tick INTEGER NOT NULL,
  source_body_id  TEXT REFERENCES game_bodies(id),
  dest_body_id    TEXT REFERENCES game_bodies(id),
  signal_kind     TEXT NOT NULL              -- 'transmission'|'broadcast'|'narrowbeam'
);

CREATE INDEX idx_sigint_observer ON sigint_events(observer_faction_id, detected_at_tick);

-- ============================================================================
-- SECTION 5 — Diplomacy: treaties + senate
-- ============================================================================

-- Treaties are public game objects with finite duration in ticks.
CREATE TABLE treaties (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  kind            TEXT NOT NULL,            -- 'nap'|'defense_pact'|'trade'|'intel_share'|'demilitarization'
  status          TEXT NOT NULL DEFAULT 'proposed',  -- 'proposed'|'active'|'expired'|'broken'|'cancelled'
  proposed_at_tick INTEGER NOT NULL,
  signed_at_tick  INTEGER,
  expires_at_tick INTEGER,                  -- NULL = open-ended
  broken_at_tick  INTEGER,
  breaker_faction_id TEXT REFERENCES game_factions(id),
  terms           TEXT NOT NULL DEFAULT '{}'  -- JSON; e.g. tariff rates, demilitarized bodies
);

CREATE INDEX idx_treaties_game_status ON treaties(game_id, status);

-- M2M: signatories of a treaty. The treaty becomes 'active' once every
-- signatory row has signed_at_tick set.
CREATE TABLE treaty_signatories (
  treaty_id   TEXT NOT NULL REFERENCES treaties(id) ON DELETE CASCADE,
  faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  signed_at_tick INTEGER,
  PRIMARY KEY (treaty_id, faction_id)
);

-- Senate proposals run weekly (every senate_period_ticks). Lifecycle:
-- proposed -> debating -> voting -> resolved.
CREATE TABLE senate_proposals (
  id                 TEXT PRIMARY KEY,
  game_id            TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  proposer_faction_id TEXT REFERENCES game_factions(id),  -- NULL for system-generated
  kind               TEXT NOT NULL,         -- 'trade'|'military'|'scientific'|'recognition'|'sanction'|'crisis'
  title              TEXT NOT NULL,
  summary            TEXT NOT NULL,
  payload            TEXT NOT NULL DEFAULT '{}',  -- JSON; structure depends on kind
  status             TEXT NOT NULL DEFAULT 'debating', -- 'debating'|'voting'|'passed'|'failed'|'withdrawn'
  proposed_at_tick   INTEGER NOT NULL,
  vote_opens_at_tick INTEGER NOT NULL,
  vote_closes_at_tick INTEGER NOT NULL,
  resolved_at_tick   INTEGER,
  -- if passed, the modifier applies for the design-doc default of 7 ticks
  effect_until_tick  INTEGER
);

CREATE INDEX idx_senate_status ON senate_proposals(game_id, status, vote_closes_at_tick);

CREATE TABLE senate_votes (
  proposal_id TEXT NOT NULL REFERENCES senate_proposals(id) ON DELETE CASCADE,
  faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  vote        TEXT NOT NULL,                -- 'yea'|'nay'|'abstain'
  weight      INTEGER NOT NULL,             -- snapshot of senate_weight at vote time
  cast_at_tick INTEGER NOT NULL,
  PRIMARY KEY (proposal_id, faction_id)
);

-- ============================================================================
-- SECTION 6 — Technology
-- ============================================================================

-- Per-faction tech progress. The tech catalog itself (ids, costs, branches,
-- prerequisites) lives in worker code as static seed data. This table just
-- records what each faction has unlocked.
CREATE TABLE faction_techs (
  game_id     TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  tech_id     TEXT NOT NULL,                -- e.g. 'prop.high_isp', 'sensors.deep_array'
  status      TEXT NOT NULL,                -- 'researching'|'completed'
  started_at_tick   INTEGER NOT NULL,
  completed_at_tick INTEGER,
  PRIMARY KEY (game_id, faction_id, tech_id)
);

CREATE INDEX idx_faction_techs_status ON faction_techs(game_id, faction_id, status);

-- ============================================================================
-- SECTION 7 — Messages and chronicle
-- ============================================================================

-- Messages are faction-to-faction (or broadcast). A signed message carries
-- the cryptographic guarantee that the named sender produced it. v2 forgery
-- introduces a distinction between claimed and actual sender; for v1 the
-- two columns hold the same value but exist now to avoid migration churn.
CREATE TABLE messages (
  id                 TEXT PRIMARY KEY,
  game_id            TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  actual_sender_faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  claimed_sender_faction_id TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  scope              TEXT NOT NULL,         -- 'dm'|'group'|'broadcast'
  body               TEXT NOT NULL,
  signed             INTEGER NOT NULL DEFAULT 0,  -- 0/1; if 1, signature verifiable from public state
  sent_at_tick       INTEGER NOT NULL,
  sent_at_ms         INTEGER NOT NULL
);

CREATE INDEX idx_messages_game_tick ON messages(game_id, sent_at_tick DESC);

-- Recipients for dm/group; for broadcast, no rows are inserted and the
-- message is visible to every faction by virtue of scope.
CREATE TABLE message_recipients (
  message_id  TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  read_at_ms  INTEGER,
  PRIMARY KEY (message_id, faction_id)
);

-- Append-only event log. Every significant game event writes one row here.
-- This is the artifact players keep at end of match; UI is the chronicle viewer.
CREATE TABLE chronicle_entries (
  id                 TEXT PRIMARY KEY,
  game_id            TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  tick_number        INTEGER NOT NULL,
  kind               TEXT NOT NULL,         -- 'treaty_signed'|'treaty_broken'|'declaration'|'senate_vote'|
                                            -- 'battle'|'body_claimed'|'body_developed'|'ship_built'|
                                            -- 'ship_destroyed'|'faction_eliminated'|'tech_completed'|
                                            -- 'victory'|'game_started'|'game_ended'
  actor_faction_id   TEXT REFERENCES game_factions(id),
  target_faction_id  TEXT REFERENCES game_factions(id),
  body_id            TEXT REFERENCES game_bodies(id),
  ship_id            TEXT REFERENCES game_ships(id),
  payload            TEXT NOT NULL DEFAULT '{}',  -- JSON; freeform per kind
  visibility         TEXT NOT NULL DEFAULT 'public',  -- 'public' | JSON array of faction ids
  created_at_ms      INTEGER NOT NULL
);

CREATE INDEX idx_chronicle_game_tick ON chronicle_entries(game_id, tick_number, id);
CREATE INDEX idx_chronicle_kind ON chronicle_entries(game_id, kind);

-- ============================================================================
-- SECTION 8 — Orders, snapshots, reserved v2
-- ============================================================================

-- Catch-all for cross-cutting orders that don't fit a single domain table.
-- Most orders are NOT here — committing a maneuver is a node status flip,
-- queuing a build is a row in game_body_build_queue, voting is a row in
-- senate_votes. Use this only for actions that don't have a natural home.
CREATE TABLE pending_orders (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id      TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  kind            TEXT NOT NULL,             -- 'sigint_scan'|'signed_declaration'|'custom'
  payload         TEXT NOT NULL DEFAULT '{}',
  submitted_at_ms INTEGER NOT NULL,
  target_tick     INTEGER NOT NULL,          -- the tick at which this is resolved
  status          TEXT NOT NULL DEFAULT 'pending', -- 'pending'|'applied'|'rejected'|'cancelled'
  applied_at_tick INTEGER,
  rejection_reason TEXT
);

CREATE INDEX idx_orders_target_tick ON pending_orders(game_id, target_tick, status);

-- Reserved for v2 standing-orders engine. Schema is defined now so the v2
-- migration is additive. No worker code should read/write this table in v1.
CREATE TABLE standing_orders (
  id              TEXT PRIMARY KEY,
  game_id         TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id      TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  trigger_kind    TEXT NOT NULL,
  trigger_payload TEXT NOT NULL DEFAULT '{}',
  action_kind     TEXT NOT NULL,
  action_payload  TEXT NOT NULL DEFAULT '{}',
  enabled         INTEGER NOT NULL DEFAULT 1,
  created_at_tick INTEGER NOT NULL,
  last_fired_tick INTEGER
);

CREATE INDEX idx_standing_orders_faction ON standing_orders(game_id, faction_id, enabled);

-- Per-tick snapshot for rollback / chronicle replay. JSON blob; lossy and
-- not authoritative. The relational rows are the source of truth.
CREATE TABLE game_snapshots (
  game_id        TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  tick_number    INTEGER NOT NULL,
  state_blob     TEXT NOT NULL,             -- JSON dump of derived per-faction views
  bytes          INTEGER NOT NULL,          -- length of state_blob; for storage telemetry
  created_at_ms  INTEGER NOT NULL,
  PRIMARY KEY (game_id, tick_number)
);

-- ============================================================================
-- END
-- ============================================================================
` },
  { name: "0004_senate_effects.sql", sql: `-- ============================================================================
-- Orbital — Senate Effects (v1)
-- ============================================================================
--
-- Adds the deferred-application table for senate slider laws. When a senate
-- proposal passes, the resolver inserts a row here with the slider id, the
-- chosen value, and the active tick window. Other systems (tick processor,
-- build cost calc, fuel yield, combat) read this table to compute the
-- effective slider value for a given (game_id, slider_id, current_tick).
--
-- The slider catalog itself (id, label, range, default) lives in worker
-- code (\`src/senate.js\`); this table holds only the per-game active overrides.
-- ============================================================================

CREATE TABLE senate_effects (
  id                 TEXT PRIMARY KEY,
  game_id            TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  slider_id          TEXT NOT NULL,
  value              REAL NOT NULL,
  proposal_id        TEXT REFERENCES senate_proposals(id) ON DELETE SET NULL,
  active_from_tick   INTEGER NOT NULL,
  active_until_tick  INTEGER NOT NULL,
  created_at_tick    INTEGER NOT NULL,
  created_at_ms      INTEGER NOT NULL
);

-- Most-recent active effect lookup: "for game G, slider S, at tick T, what's
-- the effect row where active_from_tick <= T < active_until_tick?".
CREATE INDEX idx_senate_effects_lookup
  ON senate_effects(game_id, slider_id, active_until_tick, active_from_tick);

CREATE INDEX idx_senate_effects_game ON senate_effects(game_id);
` },
  { name: "0005_empire_identity_and_starter_fleet.sql", sql: `-- Pre-game empire identity (set in lobby, carried into the game).
-- empire_name overrides the rotating-default faction name; bio is freeform
-- player-authored flavor text shown in the faction roster / diplomacy UI.
ALTER TABLE room_members ADD COLUMN empire_name TEXT;
ALTER TABLE room_members ADD COLUMN bio TEXT;

-- Bio carried through to the in-game faction record so it survives
-- after the lobby row could in principle be cleared.
ALTER TABLE game_factions ADD COLUMN bio TEXT;
` },
  { name: "0006_trade_offers.sql", sql: `-- ============================================================================
-- Orbital — Trade Offers (Civ/Stellaris-style diplomacy negotiation)
-- ============================================================================
--
-- Design notes:
--
-- 1. trade_offers vs treaties. The existing treaties table (0003) stores
--    finalized, signed agreements. trade_offers stores the back-and-forth
--    negotiation that precedes a treaty: A offers X for Y, B counters with
--    Y' for X, A accepts. When an offer is accepted, resource transfers
--    happen atomically AND any agreed pacts create rows in treaties.
--
-- 2. Counter-offer chains. A counter creates a NEW row that points at its
--    predecessor via parent_offer_id. The predecessor flips to 'countered'.
--    Walking back through parent_offer_id reconstructs the negotiation
--    history for the UI.
--
-- 3. Resource payload uses the four server-side faction resources
--    (metal/fuel/gold/science) directly. The client maps these to its
--    own display labels.
--
-- 4. Pacts. offer_pacts and request_pacts are JSON arrays of treaty kinds
--    ('nap', 'defense_pact', 'intel_share') that the side offering them
--    will sign if the trade is accepted. Empty array = no pacts offered.
--
-- 5. Visibility. An offer is visible to its proposer and its responder
--    only, plus optionally to spectators (not implemented in v1).
-- ============================================================================

CREATE TABLE trade_offers (
  id                    TEXT PRIMARY KEY,
  game_id               TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  proposer_faction_id   TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  responder_faction_id  TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  status                TEXT NOT NULL DEFAULT 'open',
    -- 'open'      : awaiting responder action
    -- 'accepted'  : responder accepted; resources & pacts applied
    -- 'declined'  : responder declined
    -- 'cancelled' : proposer withdrew before action
    -- 'countered' : responder made a counter-offer; superseded by child

  -- Resources offered BY proposer TO responder (proposer is paying).
  offer_metal           INTEGER NOT NULL DEFAULT 0,
  offer_fuel            INTEGER NOT NULL DEFAULT 0,
  offer_gold            INTEGER NOT NULL DEFAULT 0,
  offer_science         INTEGER NOT NULL DEFAULT 0,

  -- Resources requested BY proposer FROM responder (responder pays if accepted).
  request_metal         INTEGER NOT NULL DEFAULT 0,
  request_fuel          INTEGER NOT NULL DEFAULT 0,
  request_gold          INTEGER NOT NULL DEFAULT 0,
  request_science       INTEGER NOT NULL DEFAULT 0,

  -- Pacts that proposer offers to sign / requests responder to sign.
  -- JSON array of treaty kind strings, e.g. '["nap","intel_share"]'.
  offer_pacts           TEXT NOT NULL DEFAULT '[]',
  request_pacts         TEXT NOT NULL DEFAULT '[]',

  -- Counter-offer linkage. Walk parent_offer_id back to the original draft.
  parent_offer_id       TEXT REFERENCES trade_offers(id),

  -- Optional short note attached to the offer.
  note                  TEXT,

  created_at_tick       INTEGER NOT NULL,
  created_at_ms         INTEGER NOT NULL,
  resolved_at_ms        INTEGER,
  resolved_by_faction_id TEXT REFERENCES game_factions(id)
);

CREATE INDEX idx_trades_game_status ON trade_offers(game_id, status);
CREATE INDEX idx_trades_responder   ON trade_offers(responder_faction_id, status);
CREATE INDEX idx_trades_proposer    ON trade_offers(proposer_faction_id, status);
CREATE INDEX idx_trades_parent      ON trade_offers(parent_offer_id);
` },
  { name: "0007_rooms_invite_password.sql", sql: `-- Add invite codes and optional passwords to rooms.
-- invite_code: short URL-safe random string for "join by code" flow.
-- password_hash: NULL = open room; otherwise pbkdf2$... matches the
--   same format as users.password_hash (verifyPassword in worker/auth.js).

ALTER TABLE rooms ADD COLUMN invite_code TEXT;
ALTER TABLE rooms ADD COLUMN password_hash TEXT;

CREATE UNIQUE INDEX idx_rooms_invite_code ON rooms(invite_code) WHERE invite_code IS NOT NULL;
` },
  { name: "0008_starting_body.sql", sql: `-- Per-member chosen starting body. References a template id from the
-- worker's BODY_CATALOG (e.g. 'inara', 'verda', 'rust'). Null means
-- auto-assign at game start (the legacy behavior).
ALTER TABLE room_members ADD COLUMN chosen_starting_body TEXT;
` },
  { name: "0009_ship_combat.sql", sql: `-- Combat state on each ship row. Damage and HP mirror the client's
-- src/game/shipClasses.ts so server resolution stays balanced with
-- the player's intuition. damage_per_tick is the auto-fire rate at
-- a body shared with a hostile faction. status already exists; we
-- repurpose 'destroyed' (was reserved) once hp falls to zero.

ALTER TABLE game_ships ADD COLUMN hp REAL NOT NULL DEFAULT 100;
ALTER TABLE game_ships ADD COLUMN hp_max REAL NOT NULL DEFAULT 100;
ALTER TABLE game_ships ADD COLUMN damage_per_tick REAL NOT NULL DEFAULT 0;
` },
  { name: "0010_game_settlements.sql", sql: `-- Cities + orbital stations mirrored to D1 so the multiplayer canvas
-- can paint them server-authoritatively (and so the tick resolver can
-- harvest yields into settlement stockpiles).
--
-- type = 'city' has surface_angle (radians around body's surface).
-- type = 'station' has orbit_* elements (Keplerian orbit around body).
-- The columns the wrong type doesn't need are simply NULL.

CREATE TABLE game_settlements (
  id                  TEXT PRIMARY KEY,
  game_id             TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  body_id             TEXT NOT NULL REFERENCES game_bodies(id) ON DELETE CASCADE,
  owner_faction_id    TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  type                TEXT NOT NULL,          -- 'city' | 'station'
  name                TEXT NOT NULL,
  hp                  REAL NOT NULL,
  hp_max              REAL NOT NULL,
  population          INTEGER NOT NULL DEFAULT 1,
  -- surface placement (city) or orbit (station)
  surface_angle       REAL,
  orbit_rp            REAL,
  orbit_ra            REAL,
  orbit_omega         REAL,
  orbit_m0            REAL,
  orbit_epoch         REAL,
  -- per-settlement stockpile (matches game_factions resource columns)
  stockpile_metal     INTEGER NOT NULL DEFAULT 0,
  stockpile_fuel      INTEGER NOT NULL DEFAULT 0,
  stockpile_gold      INTEGER NOT NULL DEFAULT 0,
  stockpile_science   INTEGER NOT NULL DEFAULT 0,
  -- lifecycle
  created_at_tick     INTEGER NOT NULL,
  last_growth_tick    INTEGER,
  last_harvest_tick   INTEGER,
  last_combat_tick    INTEGER,
  destroyed_at_tick   INTEGER
);

CREATE INDEX idx_settlements_game ON game_settlements(game_id);
CREATE INDEX idx_settlements_body ON game_settlements(body_id);
CREATE INDEX idx_settlements_owner ON game_settlements(owner_faction_id);
` },
  { name: "0011_node_arrival_at_tick.sql", sql: `-- Track the predicted Hohmann arrival tick on a maneuver node so the
-- tick resolver can separate "fired" from "arrived". Used to keep
-- in-flight ships visible (and animatable) on the canvas between
-- scheduled_t (departure burn) and arrival_at_tick (insertion burn).
-- NULL means the node hasn't fired yet, or it predates this migration.

ALTER TABLE game_ship_nodes ADD COLUMN arrival_at_tick INTEGER;
` },
  { name: "0012_faction_tech_level.sql", sql: `-- Add a level counter to faction_techs so the server can track infinite
-- Stellaris-style repeatables. The original schema only carried a
-- 'researching' / 'completed' status with no notion of how many times the
-- tech had been advanced. The level column reaches >0 once the first
-- buy-up has happened; status flips between researching/completed for the
-- current-in-progress tier (unused for instant-research v1, kept for the
-- future progress-bar model).

ALTER TABLE faction_techs ADD COLUMN level INTEGER NOT NULL DEFAULT 0;
` },
  { name: "0013_turn_based_mode.sql", sql: `-- Turn-Based Mode (MP, prototype).
--
-- Adds two game-level config columns + a per-faction commit ledger. When
-- a game has \`turn_based_enabled = 1\`, the Room DO's wall-clock alarm
-- stops auto-advancing the tick; instead the tick batch fires from
-- POST /api/games/:gameId/turn/commit once every faction has committed
-- the current turn.
--
-- The \`current_turn_number\` lives on \`games\` so a player's commit ledger
-- entry maps unambiguously back to "which turn this was for", even if
-- two players double-click in the same millisecond. After a successful
-- batch the worker increments \`current_turn_number\` and clears any
-- now-stale \`game_turn_commits\` rows.

ALTER TABLE games ADD COLUMN turn_based_enabled INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN ticks_per_turn INTEGER NOT NULL DEFAULT 20;
ALTER TABLE games ADD COLUMN current_turn_number INTEGER NOT NULL DEFAULT 0;

-- One row per (game, faction, turn) pair recording when that faction
-- declared themselves ready to advance. Composite PK doubles as the
-- "already committed?" idempotency guard so a double-tap on the COMMIT
-- TURN button can't double-fire the batch.
CREATE TABLE IF NOT EXISTS game_turn_commits (
  game_id         TEXT    NOT NULL,
  faction_id      TEXT    NOT NULL,
  turn_number     INTEGER NOT NULL,
  committed_at_ms INTEGER NOT NULL,
  PRIMARY KEY (game_id, faction_id, turn_number)
);

CREATE INDEX IF NOT EXISTS idx_turn_commits_game_turn
  ON game_turn_commits(game_id, turn_number);
` },
  { name: "0014_settlement_collectors.sql", sql: `-- Collector network endpoint flag for settlements.
--
-- A collector is a logistics endpoint that lets stockpile drain to the
-- empire pool. Without one, every settlement piles resources locally
-- with nowhere to land. Capitals start with one (set in
-- worker/factions.js seedGameWorld); every other has to be built via
-- POST /api/games/:gameId/settlements/:settlementId/collector.
--
-- Tracked tick-of-construction is informational only — surfaces in the
-- BodyInspector as "built T+123". NULL on the free capital collector
-- so the UI can distinguish "starter" from "built-by-the-player."

ALTER TABLE game_settlements ADD COLUMN has_collector INTEGER NOT NULL DEFAULT 0;
ALTER TABLE game_settlements ADD COLUMN collector_built_tick INTEGER;
` },
  { name: "0015_settlement_buildings.sql", sql: `-- Settlement upgrade buildings (forge / mint / lab / weapons / shipyard).
--
-- The client has full UI for queueing per-settlement building upgrades
-- and a per-tick completion loop. The server was missing the schema +
-- endpoints entirely, so any MP build was wiped by the next /state poll
-- (same failure mode as the collector flag pre-0014).
--
-- Schema decision: JSON columns rather than join tables. Both blobs are
-- small (max 5 keys for buildings, single object for the order) and
-- they're always read together with the settlement row. A join table
-- would be cleaner but mean two extra queries per /state response.
--
--   buildings_json     {"forge": 2, "mint": 0, "lab": 1, ...}
--                      Missing key or 0 = not built.
--
--   building_order_json
--     {"kind": "forge", "target_level": 3,
--      "start_tick": 100, "complete_tick": 120}
--     NULL when nothing is in flight. One concurrent upgrade per
--     settlement — players have to spread their economy.

ALTER TABLE game_settlements ADD COLUMN buildings_json TEXT;
ALTER TABLE game_settlements ADD COLUMN building_order_json TEXT;
` },
  { name: "0016_trade_routes.sql", sql: `-- Trade routes (MP).
--
-- A trade route is a recurring freighter ferry between an origin
-- settlement and a destination collector. The Room DO alarm
-- auto-pilots the freighter: pick up at origin → fly to dest → drop
-- off → fly back → repeat until cancelled. If the freighter is
-- destroyed mid-route, the cargo is captured by the killer's pool
-- (piracy, handled in the combat block of resolveTick).
--
-- Columns mirror the client TradeRoute type. Server uses metal/gold
-- column names; the client maps to ore/credits at the deserialization
-- boundary (same convention as game_settlements.stockpile_*).
--
-- One active route per ship. If a player creates a second route for
-- the same freighter we replace the existing one (UI guard already
-- prevents this; the server still validates).

CREATE TABLE game_trade_routes (
  id                TEXT PRIMARY KEY,
  game_id           TEXT NOT NULL,
  owner_faction_id  TEXT NOT NULL,
  ship_id           TEXT NOT NULL,
  origin_body_id    TEXT NOT NULL,
  dest_body_id      TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'returning',
                    -- 'outbound'  = heading toward dest (cargo full)
                    -- 'returning' = heading toward origin (cargo empty)
                    -- 'paused'    = player paused; auto-pilot skips
  cargo_fuel        REAL NOT NULL DEFAULT 0,
  cargo_metal       REAL NOT NULL DEFAULT 0,
  cargo_gold        REAL NOT NULL DEFAULT 0,
  cargo_science     REAL NOT NULL DEFAULT 0,
  created_at_tick   INTEGER NOT NULL,
  cancelled_at_tick INTEGER
);

CREATE INDEX idx_trade_routes_game ON game_trade_routes(game_id, cancelled_at_tick);
CREATE UNIQUE INDEX idx_trade_routes_ship_active
  ON game_trade_routes(ship_id) WHERE cancelled_at_tick IS NULL;
` },
  { name: "0017_force_finish_bezier_transfers.sql", sql: `-- Force-finish all in-flight legacy Bezier transfers.
--
-- Phase 6 of the Bezier→Torch migration. The game's transfer model
-- changed from precomputed Hohmann-Bezier curves to a constant-thrust
-- (torch) brachistochrone integrated tick-by-tick. The new client
-- ignores legacy ship.transfer / ship.pendingTransfer fields and
-- drives ships via ship.transit instead.
--
-- Per the deploy plan (Q3 option B from the original migration spec):
-- any maneuver node that's currently committed-but-not-fired OR
-- in_transit at the moment this migration runs gets force-finished.
-- The ship is teleported into a parking orbit around the target body,
-- the node is marked 'cancelled', and any subsequent post-Bezier code
-- path that touched ship.transfer becomes a no-op.
--
-- Without this migration, active multiplayer games at deploy time
-- would silently lose their in-flight transfers (the new client
-- doesn't read those rows anymore) and players would see ships
-- frozen at their departure body forever.

-- Step 1: park ships sitting on an in-flight transfer at their
-- destination body. The ship's parent_body_id swaps to the target,
-- orbit elements reset to a clean low-altitude circular orbit, and
-- epoch is bumped to current_tick so the new orbit is "fresh."
--
-- D1 (SQLite) supports correlated subqueries in UPDATE — we use one
-- per column rather than a JOIN-update (which it doesn't support).
-- The CASE on b.radius pulls a sensible parking altitude (1.5×
-- body radius) when the body row exists; falls back to 6 game units.
UPDATE game_ships
SET
  parent_body_id = (
    SELECT n.target_body_id
    FROM game_ship_nodes n
    WHERE n.ship_id = game_ships.id
      AND n.status IN ('committed', 'in_transit')
      AND n.target_body_id IS NOT NULL
    LIMIT 1
  ),
  orbit_rp = (
    SELECT COALESCE(b.radius, 4) * 1.5
    FROM game_ship_nodes n
    LEFT JOIN game_bodies b ON b.id = n.target_body_id AND b.game_id = n.game_id
    WHERE n.ship_id = game_ships.id
      AND n.status IN ('committed', 'in_transit')
      AND n.target_body_id IS NOT NULL
    LIMIT 1
  ),
  orbit_ra = (
    SELECT COALESCE(b.radius, 4) * 1.5
    FROM game_ship_nodes n
    LEFT JOIN game_bodies b ON b.id = n.target_body_id AND b.game_id = n.game_id
    WHERE n.ship_id = game_ships.id
      AND n.status IN ('committed', 'in_transit')
      AND n.target_body_id IS NOT NULL
    LIMIT 1
  ),
  orbit_omega = 0,
  orbit_m0 = 0,
  orbit_direction = 1,
  orbit_epoch = (
    SELECT g.current_tick
    FROM games g
    WHERE g.id = game_ships.game_id
  )
WHERE id IN (
  SELECT DISTINCT n.ship_id
  FROM game_ship_nodes n
  WHERE n.status IN ('committed', 'in_transit')
    AND n.target_body_id IS NOT NULL
);

-- Step 2: cancel every committed/in_transit transfer node so the
-- alarm doesn't try to re-fire or arrive-process them. We deliberately
-- DON'T delete the rows so the chronicle/history still has a record;
-- the alarm code already skips status='cancelled'.
UPDATE game_ship_nodes
SET status = 'cancelled'
WHERE status IN ('committed', 'in_transit');

-- Add a faction-level engineG column so the torch executor (both
-- client and any future server-side torch integration) can scale
-- trip times by engine research. Default matches DEFAULT_ENGINE_G
-- in src/physics/torchTransfer.ts (0.05g — research-level-0 baseline).
ALTER TABLE game_factions ADD COLUMN engine_g REAL DEFAULT 0.05;
` },
  { name: "0018_dyson_sphere.sql", sql: `-- ============================================================================
-- Orbital — Dyson Sphere megaproject (Engineering Victory)
-- ============================================================================
--
-- One sphere per match. The faction that lays the foundation at a Sol-orbit
-- station becomes the controller. Per tick, every parked freighter the
-- controller owns at Sol drains a fixed quota from their empire pool and
-- contributes it to the sphere. Completing the sphere (hp >= max_hp)
-- triggers Engineering Victory.
--
-- Damage: the sphere absorbs damage routed through its foundation station
-- (see worker/room.js Dyson damage block in resolveTick). Damage reduces
-- hp and proportionally scales the accumulated resources so the progress
-- bar stays coherent. hp=0 collapses the sphere; the foundation slot
-- reopens for the next builder.
--
-- The state lives as nullable columns on the games row so we don't need a
-- separate table for a single megaproject per match. Worker code reads:
--   dyson_controller_faction_id IS NULL  → no sphere yet, slot open
--   ELSE                                  → sphere active, columns populated
-- ============================================================================

ALTER TABLE games ADD COLUMN dyson_controller_faction_id TEXT REFERENCES game_factions(id) ON DELETE SET NULL;
ALTER TABLE games ADD COLUMN dyson_foundation_settlement_id TEXT REFERENCES game_settlements(id) ON DELETE SET NULL;
ALTER TABLE games ADD COLUMN dyson_started_at_tick INTEGER;
ALTER TABLE games ADD COLUMN dyson_acc_fuel    INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_acc_ore     INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_acc_credits INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_acc_science INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_target_fuel    INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_target_ore     INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_target_credits INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_target_science INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_hp     INTEGER NOT NULL DEFAULT 0;
ALTER TABLE games ADD COLUMN dyson_max_hp INTEGER NOT NULL DEFAULT 0;

CREATE INDEX idx_games_dyson_controller ON games(dyson_controller_faction_id);
` },
  { name: "0019_dyson_damage_tracking.sql", sql: `-- ============================================================================
-- Orbital — Dyson Sphere damage-delta tracking
-- ============================================================================
--
-- Phase B shipped the sphere with collapse-on-foundation-destruction as the
-- only server-side loss vector. To let combat damage actually contest a
-- sphere in MP, the server tick processor needs to know how much HP the
-- foundation station lost since the last tick. We track that as a single
-- "last seen" column on the games row: each tick, tickDysonSphere reads
-- the foundation's current HP, compares to last_seen, applies the delta
-- to the sphere proportionally, then writes current HP back into the
-- column for next tick. NULL means "not initialized yet" — first read
-- after foundation-laying seeds it without applying damage.
-- ============================================================================

ALTER TABLE games ADD COLUMN dyson_station_last_hp INTEGER;
` },
  { name: "0020_ship_veterancy.sql", sql: `-- Ship veterancy + combat history (matches src/game/combat.ts + types.ts).
--
-- Every confirmed ship kill grants the killer hull +1 rank. Each rank
-- gives +1% damage output and +1% effective max HP. Stacks
-- multiplicatively with the faction-level Weapons/Armor tech mods.
--
-- \`combat_history\` is a JSON blob holding the last 20 kills as
-- ShipKillRecord[]: { tick, targetName, targetClass, atBodyId }.
-- Stored as TEXT (sqlite JSON1 is available but the worker code
-- treats it as plain JSON.parse on read, JSON.stringify on write).
-- Capped client- and server-side so the column stays small.
--
-- Both columns are nullable / defaulted so existing rows backfill
-- cleanly without a migration write — fresh hulls and pre-veterancy
-- saves both read as rank=0 / history=[].

ALTER TABLE game_ships ADD COLUMN rank INTEGER NOT NULL DEFAULT 0;
ALTER TABLE game_ships ADD COLUMN combat_history TEXT;
` },
  { name: "0021_body_secrets.sql", sql: `-- Body secrets — hidden surprises seeded onto non-capital bodies at
-- game start. Match the client-side BodySecret model in src/types.ts +
-- src/game/secrets.ts. Server-side authoritative: server picks the
-- placements deterministically from map_seed at seedGameWorld time
-- (factions.js), and the reveal handler fires inside resolveTick
-- (room.js) the first tick a ship reaches a body with an unrevealed
-- secret.
--
-- Hidden from /state until revealed; clients must not see secret_kind
-- on bodies their ships haven't visited (see worker/state.js).
--
-- Kinds (one of BodySecretKind in client types):
--   portal_to_sun     persistent warp-to-Sol effect on arrival
--   ancient_city      discoverer gets a free city + Lab L2
--   free_collector    discoverer gets a free city with has_collector=1
--   derelict_warship  discoverer gets a free destroyer at the body
--   resource_cache    discoverer's pool gets +500 metal + 500 gold
--   ancient_databank  discoverer gets a +1 level in a random tech track
--
-- All new columns default to NULL/0 so existing bodies backfill clean.

ALTER TABLE game_bodies ADD COLUMN secret_kind TEXT;
ALTER TABLE game_bodies ADD COLUMN secret_revealed INTEGER NOT NULL DEFAULT 0;
ALTER TABLE game_bodies ADD COLUMN secret_discovered_by_faction_id TEXT;
ALTER TABLE game_bodies ADD COLUMN secret_discovered_at_tick INTEGER;
` },
  { name: "0022_ship_icon_variant.sql", sql: `-- Ship icon variant — player's per-build pick from the 6 candidates
-- per class (A..F). Carried from build queue → spawned ship row so
-- the renderer can draw the icon the player chose at construction
-- time, not the class default.
--
-- icon_variant is a single character: 'A'..'F'. NULL means
-- "use the class default" — saves the row when older clients post
-- without the field. The client falls back to DEFAULT_SHIP_ICONS
-- at render time, so a missing column never breaks rendering.

ALTER TABLE game_body_build_queue ADD COLUMN icon_variant TEXT;
ALTER TABLE game_ships ADD COLUMN icon_variant TEXT;
` },
  { name: "0023_cargo_to_freighter.sql", sql: `-- Normalize starter-Hauler ship class.
--
-- factions.js seeded haulers as ship_class = 'cargo' but every other
-- server check (handleDeploySettlement no_presence, handleQueueTradeRoute,
-- harvest loop in tickHarvest, settlement-resource pickup gating) hard-
-- codes 'freighter'. Net effect: a starter Hauler reads as 'freighter'
-- on the client (translateShipClass maps cargo→freighter) but never
-- matches any of the freighter-only gates server-side. Player tries to
-- deploy a city — server returns no_presence even though the Hauler is
-- right there at the body.
--
-- Fix: collapse 'cargo' onto 'freighter' so the one source of truth
-- across the codebase wins. Also covers any legacy 'hauler' rows from
-- earlier prototyping (translateShipClass already accepts both).
UPDATE game_ships
   SET ship_class = 'freighter'
 WHERE ship_class IN ('cargo', 'hauler');
` },
  { name: "0024_rogue_asteroids.sql", sql: `-- Rogue asteroids — small settable bodies that can be weaponized.
--
-- Two pieces:
--
-- 1. Eccentric Kepler orbit columns on game_bodies. Existing bodies all
--    use circular orbits (orbit_radius + orbit_period only — angle is
--    linear in t). The new Kuiper-class rogue asteroids have long
--    eccentric paths that need full Kepler elements. When orbit_rp /
--    orbit_ra / orbit_omega / orbit_m0 are all present, bodyPosition
--    switches to Kepler propagation; otherwise the legacy circular
--    shortcut still applies. All defaulted to NULL so every existing
--    body keeps its current path.
--
-- 2. Ram plan columns. When a faction triggers the RAM action via the
--    Trajectory Control Thrusters building, the asteroid's natural
--    orbit is replaced by a torch transit toward another body. Plan
--    values are written here; bodyPosition's render path checks
--    ram_target_body_id and integrates the torch when present.
--    Cleared (with destroyed_at_tick set) when the impact fires.

-- Eccentric orbit columns
ALTER TABLE game_bodies ADD COLUMN orbit_rp REAL;
ALTER TABLE game_bodies ADD COLUMN orbit_ra REAL;
ALTER TABLE game_bodies ADD COLUMN orbit_omega REAL;
ALTER TABLE game_bodies ADD COLUMN orbit_m0 REAL;

-- Ram plan columns
ALTER TABLE game_bodies ADD COLUMN ram_target_body_id TEXT;
ALTER TABLE game_bodies ADD COLUMN ram_start_tick INTEGER;
ALTER TABLE game_bodies ADD COLUMN ram_flip_tick INTEGER;
ALTER TABLE game_bodies ADD COLUMN ram_arrive_tick INTEGER;
ALTER TABLE game_bodies ADD COLUMN ram_acceleration REAL;
ALTER TABLE game_bodies ADD COLUMN ram_start_pos_x REAL;
ALTER TABLE game_bodies ADD COLUMN ram_start_pos_y REAL;
ALTER TABLE game_bodies ADD COLUMN ram_start_vel_x REAL;
ALTER TABLE game_bodies ADD COLUMN ram_start_vel_y REAL;
ALTER TABLE game_bodies ADD COLUMN ram_intercept_pos_x REAL;
ALTER TABLE game_bodies ADD COLUMN ram_intercept_pos_y REAL;
ALTER TABLE game_bodies ADD COLUMN ram_total_dv REAL;
ALTER TABLE game_bodies ADD COLUMN ram_owned_by_faction_id TEXT;

-- Destruction marker — set when an asteroid's ram completes (it's
-- consumed in the impact) or in the rare case an asteroid is hit by
-- another's ram. /state filters these out.
ALTER TABLE game_bodies ADD COLUMN destroyed_at_tick INTEGER;
` },
  { name: "0025_freighter_trade_log.sql", sql: `-- Freighter trade-route completion counter.
--
-- Every time a freighter on an active trade route reaches the dest
-- body with cargo and dumps it into the faction pool, this counter
-- bumps by 1. The ShipPanel "Combat Record" section is replaced with
-- a "Trade Log" view for freighters — they're hauling cargo, not
-- killing things, so showing 0 confirmed kills was a category error.
--
-- Defaulted to 0 so existing freighters backfill cleanly with no
-- migration write. Capped per-faction-per-game in practice (no hard
-- ceiling); a 4000-tick game with one freighter cycling Earth↔Mars
-- (~10 ticks per leg) can rack up ~400 deliveries — still fits in
-- INTEGER comfortably.

ALTER TABLE game_ships ADD COLUMN trades_completed INTEGER NOT NULL DEFAULT 0;
` },
  { name: "0026_ship_combat_cadence.sql", sql: `-- Combat cadence on game_ships.
--
-- Previously the worker's per-tick combat loop in worker/room.js fired
-- every server tick (no gate). At default MP tick rate (7.5 real
-- minutes per tick) that put one volley every 7.5 minutes, but the
-- effective DPS still ran 20× faster than the SP equivalent — which
-- has always paced combat at AUTO_COMBAT_INTERVAL=20 ticks per volley.
--
-- This column lets the MP combat loop track when each ship last fired
-- so a cadence gate (currently 3 ticks, see AUTO_COMBAT_INTERVAL in
-- src/game/combat.ts) can apply consistently between SP and MP. Ships
-- that have never fired read NULL → treated as -Infinity by the
-- comparison, so the gate passes on the first eligible tick.

ALTER TABLE game_ships ADD COLUMN last_combat_tick INTEGER;
` },
  { name: "0027_google_oauth.sql", sql: `-- Google OAuth support (production-safe, additive-only).
--
-- The original SSO migration (feat/google-sso branch, numbered 0014)
-- rebuilt the entire \`users\` table to relax password_hash from NOT
-- NULL to nullable. On a live database that is DANGEROUS: this app's
-- migration runner (worker/index.js) executes each statement as its
-- own D1 call rather than one wrapped transaction, so a \`DROP TABLE
-- users\` can fire the ON DELETE CASCADE foreign keys that rooms,
-- room members, and game seats declare against users(id) — cascade-
-- wiping real lobby/game data.
--
-- This rewrite avoids the rebuild completely. Two additive changes:
--
--   1) Add google_sub: the canonical Google account ID (JWT 'sub'
--      claim). SQLite can't add a UNIQUE column inline via ALTER
--      TABLE, so the column is added plain and uniqueness is enforced
--      by a separate UNIQUE INDEX. SQLite permits multiple NULLs in a
--      unique index, so every existing (Google-less) user keeps a
--      NULL google_sub without colliding.
--
--   2) password_hash STAYS NOT NULL. Google-only accounts are
--      provisioned with password_hash = '' (empty string) instead of
--      NULL — see handleGoogleAuth in worker/index.js. verifyPassword
--      rejects '' immediately (''.split('$') has length 1, not 4), so
--      a Google-only account can never be authenticated through the
--      password form. This sidesteps the NOT NULL relaxation that
--      forced the destructive rebuild.

ALTER TABLE users ADD COLUMN google_sub TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_google_sub ON users(google_sub);
` },
  { name: "0028_yield_remainders.sql", sql: `-- ============================================================================
-- 0028 — Fractional yield remainders for per-tick collector delivery
-- ============================================================================
--
-- Settlements with hasCollector=1 now deliver their harvest yield directly
-- to the faction pool every tick, at a fractional rate of (yield /
-- SETTLEMENT_HARVEST_INTERVAL) per resource.
--
-- Faction-pool columns (metal/fuel/gold/science) are INTEGER, so we can't
-- store fractional cents there directly. These remainder columns accumulate
-- the sub-1 portion of each tick's delivery; when the remainder crosses 1,
-- the integer portion transfers to the pool and the residual stays here.
--
-- All four DEFAULT 0 so existing factions get a clean starting state
-- without any backfill.
-- ============================================================================

ALTER TABLE game_factions ADD COLUMN fuel_remainder    REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN metal_remainder   REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN gold_remainder    REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN science_remainder REAL NOT NULL DEFAULT 0;
` },
  { name: "0029_build_queue_ship_name.sql", sql: `-- Persist the player's custom ship name through the build queue.
--
-- Background: handleQueueBuild accepted body.ship_name per its own
-- docstring but never read it. The completion handler in room.js then
-- generated a default \`\${shipClass} T\${tick}\` name, so every custom
-- name typed in BuildPanel silently dropped. Playtester reported
-- "custom names for ships dosnt seem to work".
--
-- Additive-only: nullable column with no default. Existing queued
-- rows stay NULL and fall through to the legacy default name at
-- completion time.
ALTER TABLE game_body_build_queue ADD COLUMN ship_name TEXT;
` },
  { name: "0030_senate_proposal_durations.sql", sql: `-- ============================================================================
-- 0030 — Per-proposal debate and vote durations
-- ============================================================================
--
-- The Senate had hardcoded DEBATE_TICKS=2 and VOTE_TICKS=1 in worker/senate.js.
-- For production the proposer needs to control deliberation length per proposal
-- (a routine slider change can ratify quickly; a controversial one wants time
-- for discussion). Both columns are nullable so legacy proposals fall back to
-- the constants when the server reads them; new rows record the values that
-- were actually used so the UI can show "debate: 6 ticks" without having to
-- guess.
-- ============================================================================

ALTER TABLE senate_proposals ADD COLUMN debate_ticks INTEGER;
ALTER TABLE senate_proposals ADD COLUMN vote_ticks   INTEGER;
` },
  { name: "0031_senate_targeted_bills.sql", sql: `-- Targeted bills + new bill kinds (trade_embargo, war_authorization,
-- production_sanction). Plus a Chancellor election kind that doesn't
-- write an effects row (its "effect" is winning the match).
--
-- Existing senate_effects rows are all slider laws (effect_kind='slider'),
-- global (target_faction_id NULL). New ongoing-effect kinds re-use this
-- table with effect_kind set per bill kind and target_faction_id pointing
-- at the faction the sanction is aimed at. Reparations is a one-shot
-- credit transfer handled at proposal resolution time — it does NOT write
-- an effects row.

ALTER TABLE senate_effects ADD COLUMN effect_kind        TEXT NOT NULL DEFAULT 'slider';
ALTER TABLE senate_effects ADD COLUMN target_faction_id  TEXT REFERENCES game_factions(id);

-- Index for the common runtime query: "is there an active <kind> effect
-- aimed at this faction right now?" — embargoes asked per route, war-auth
-- asked per combat tick, production-sanction asked per harvest.
CREATE INDEX IF NOT EXISTS idx_senate_effects_target
  ON senate_effects(game_id, effect_kind, target_faction_id, active_until_tick);
` },
  { name: "0032_chronicle_flavor_override.sql", sql: `-- Player-editable flavor text for chronicle entries (EventLog Phase 3).
--
-- The EventLog generates prose flavor client-side from a template bank.
-- This lets the factions involved in an event (actor / target) — or the
-- host — rewrite that flavor into their own narrative, synced to every
-- player via /state. Last-write-wins.
--
-- Additive-only, all nullable:
--   flavor_override     the custom prose (NULL = use the generated flavor)
--   flavor_edited_by    faction id that last edited (for the attribution
--                       footer "— rewritten by X")
--   flavor_edited_at_ms wall-clock of the last edit
ALTER TABLE chronicle_entries ADD COLUMN flavor_override TEXT;
ALTER TABLE chronicle_entries ADD COLUMN flavor_edited_by TEXT;
ALTER TABLE chronicle_entries ADD COLUMN flavor_edited_at_ms INTEGER;
` },
  { name: "0033_align_ship_hp_with_client.sql", sql: `-- 0033_align_ship_hp_with_client.sql
--
-- Server/client HP table mismatch — playtester report (Lorne, 2026-06-26):
-- newly built frigates were spawning at 80/100 HP and freighters at 30/60
-- in the UI even with zero combat in the session. Root cause: the server
-- HP tables in worker/factions.js and worker/room.js were
--   frigate: 80, freighter: 30
-- but the client shipClasses.ts says
--   frigate: 100, freighter: 60
-- The HP bar renders \`ship.hp / clientDef.hp\`, so the cap mismatch was
-- visible from frame one.
--
-- This migration:
--   1. Heals any ship currently AT its old cap (= 80 frigate, = 30 freighter)
--      up to the new cap. Ships at LESS than the old cap have real combat
--      damage — they keep it. The hp_max bump (step 2) raises the ceiling
--      they can later repair to.
--   2. Bumps hp_max to the new value for every frigate / freighter still
--      sitting at the old hp_max. Future spawns will use the new table
--      (worker code is being updated in the same change).
--
-- Idempotent: re-running is a no-op once hp_max has been bumped, because
-- the WHERE clauses gate on the old values.

UPDATE game_ships
   SET hp = 100
 WHERE ship_class = 'frigate'
   AND hp = 80
   AND hp_max = 80;

UPDATE game_ships
   SET hp = 60
 WHERE ship_class = 'freighter'
   AND hp = 30
   AND hp_max = 30;

UPDATE game_ships
   SET hp_max = 100
 WHERE ship_class = 'frigate'
   AND hp_max = 80;

UPDATE game_ships
   SET hp_max = 60
 WHERE ship_class = 'freighter'
   AND hp_max = 30;
` },
  { name: "0033_ship_designs.sql", sql: `-- Ship designer (DESIGN-identity-economy.md §2).
--
-- game_ship_designs: named per-player design library. Each design is a
-- hull class + a parts loadout (parts_json: JSON array of part ids,
-- e.g. '["weapon","weapon","shield"]') + an icon variant. One ACTIVE
-- design per (faction, ship_class) — enforced in the activate handler
-- (worker/actions.js), not by a constraint, because SQLite can't
-- express a partial-unique cleanly across the migration path.
--
-- parts_json on game_body_build_queue: the active design's loadout is
-- SNAPSHOT onto the build order at queue time, so editing a design
-- never mutates queued ships.
--
-- parts_json on game_ships: copied from the build order at completion
-- (worker/room.js). NULL = bare hull = exactly today's stats — this is
-- the live-game migration story; every existing ship stays untouched.
CREATE TABLE game_ship_designs (
  id            TEXT PRIMARY KEY,
  game_id       TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id    TEXT NOT NULL REFERENCES game_factions(id) ON DELETE CASCADE,
  ship_class    TEXT NOT NULL,          -- 'corvette'|'frigate'|'destroyer'|'freighter'
  name          TEXT NOT NULL,
  parts_json    TEXT,                   -- JSON array of part ids; NULL/[] = bare hull
  icon_variant  TEXT,                   -- 'A'..'F' or NULL for class default
  is_active     INTEGER NOT NULL DEFAULT 0,
  created_at_ms INTEGER NOT NULL
);

CREATE INDEX idx_ship_designs_faction
  ON game_ship_designs(game_id, faction_id, ship_class);

ALTER TABLE game_body_build_queue ADD COLUMN parts_json TEXT;
ALTER TABLE game_ships ADD COLUMN parts_json TEXT;
` },
  { name: "0034_discord_digest_state.sql", sql: `-- 0034_discord_digest_state.sql
--
-- Bookkeeping for the daily Discord digest (worker/digest.js). One row
-- per game tracking:
--   last_digest_ms    — wall-clock of the last digest sent (gate: don't
--                       send twice in one day even if the cron re-fires)
--   last_entry_ms     — created_at_ms high-water mark of chronicle
--                       entries already reported, so each digest covers
--                       exactly the window since the previous one
--   trades_snapshot   — SUM(game_ships.trades_completed) at last digest;
--                       the delta against the live sum = "deliveries
--                       completed today"
--
-- No row = game has never been digested; the first run backfills with
-- a 24h lookback rather than the whole game history.

CREATE TABLE IF NOT EXISTS digest_state (
  game_id          TEXT PRIMARY KEY REFERENCES games(id) ON DELETE CASCADE,
  last_digest_ms   INTEGER NOT NULL DEFAULT 0,
  last_entry_ms    INTEGER NOT NULL DEFAULT 0,
  trades_snapshot  INTEGER NOT NULL DEFAULT 0
);
` },
  { name: "0034_ship_orders.sql", sql: `-- Ship standing orders (DESIGN-identity-economy.md §3).
--
--   stance          : 'attack' | 'defensive' | 'hold'. NULL = 'attack'
--                     (attack-on-sight, identical to pre-orders behavior).
--   retreat_hp_pct  : NULL | 25 | 50 | 75. When set, a damaged ship whose
--                     hp/hp_max drops to or below the threshold auto-
--                     transfers to the nearest friendly body with a
--                     shipyard-equipped station. NULL = never retreat.
--   detonate_hp_pct : NULL | 25 | 50. Dead-man switch for detonator-part
--                     hulls: auto-trigger the detonator below threshold.
--                     Inert on ships without a detonator part.
--
-- D1 requires one ALTER per statement.
ALTER TABLE game_ships ADD COLUMN stance TEXT;
ALTER TABLE game_ships ADD COLUMN retreat_hp_pct INTEGER;
ALTER TABLE game_ships ADD COLUMN detonate_hp_pct INTEGER;
` },
  { name: "0035_discord_identity.sql", sql: `-- 0035_discord_identity.sql
--
-- Two-way Discord bot: identity linking + senate voting from Discord.
--
-- 1) users.discord_id / discord_username — a player links their Discord
--    account once (in-game "Link Discord" -> a short code -> /link <code>
--    in Discord). A button click in Discord then resolves
--    discord_id -> user -> that game's faction, so a vote lands with the
--    correct planet-count weight and one-vote-per-faction semantics.
--
-- 2) discord_link_codes — short-lived one-time codes minted in-game and
--    redeemed by the /link slash command. Rows are consumed on redeem and
--    expire on TTL; a cheap sweep in the redeem path clears stale ones.
--
-- 3) discord_senate_messages — maps a senate proposal to the Discord
--    message that carries its vote buttons, so the interactions handler
--    can edit that exact message to reflect the running tally (and a
--    future "voting closed" pass can disable its buttons).

ALTER TABLE users ADD COLUMN discord_id TEXT;
ALTER TABLE users ADD COLUMN discord_username TEXT;

-- One Discord account maps to at most one Orbital user. Partial unique
-- index so the many NULLs (unlinked users) don't collide.
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_discord_id
  ON users(discord_id) WHERE discord_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS discord_link_codes (
  code        TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_discord_link_codes_user ON discord_link_codes(user_id);

CREATE TABLE IF NOT EXISTS discord_senate_messages (
  proposal_id TEXT PRIMARY KEY,
  game_id     TEXT NOT NULL,
  channel_id  TEXT NOT NULL,
  message_id  TEXT NOT NULL,
  created_at  INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_discord_senate_messages_game ON discord_senate_messages(game_id);
` },
  { name: "0036_faction_color2.sql", sql: `-- Two-tone faction colors (DESIGN-identity-economy.md §5).
-- PRIMARY (color) = ownership — all meaning stays here.
-- SECONDARY (color2) = decoration only (colorblind safety); legacy rows
-- get a derived secondary (lighten/darken of primary) at read time.
-- One ALTER per statement — D1 requirement.
ALTER TABLE game_factions ADD COLUMN color2 TEXT;
-- Lobby-side preference: players pick primary + secondary before start,
-- same pattern as empire_name / bio / chosen_starting_body (0005 / 0008).
ALTER TABLE room_members ADD COLUMN color TEXT;
ALTER TABLE room_members ADD COLUMN color2 TEXT;
` },
  { name: "0037_build_queue.sql", sql: `-- Unlimited build queue (DESIGN-identity-economy.md §7 P1c).
--
-- Before: handleQueueBuild 409'd ('no_slots') once in-flight builds at
-- a body reached concurrency = 1 + shipyard levels. Now any number of
-- orders can be queued (resources still charged at queue time); orders
-- beyond capacity wait with status='waiting' and are promoted FIFO by
-- the tick alarm as active builds complete.
--
-- Columns (all additive; SQLite constant DEFAULT backfills existing
-- rows, so every pre-migration row reads status='building' — correct,
-- they were all active under the old gate):
--
--   status          'building' (counts against slots, tick alarm
--                   completes it at completes_at_tick) or 'waiting'
--                   (inert until promoted; its completes_at_tick is a
--                   placeholder and is rewritten at promotion).
--   build_ticks     construction duration snapshot taken at queue time
--                   so promotion doesn't have to re-derive it from the
--                   ship class table. NULL on legacy rows — promotion
--                   falls back to SHIP_BUILD_COST[ship_class].
--   started_at_tick tick the build actually became active (insert time
--                   when a slot was free, promotion time otherwise).
--                   NULL on legacy + waiting rows; the client falls
--                   back to queued_at_tick for the progress bar.
ALTER TABLE game_body_build_queue ADD COLUMN status TEXT NOT NULL DEFAULT 'building';
ALTER TABLE game_body_build_queue ADD COLUMN build_ticks INTEGER;
ALTER TABLE game_body_build_queue ADD COLUMN started_at_tick INTEGER;
` },
  { name: "0038_ship_templates.sql", sql: `-- Cross-game ship templates.
--
-- game_ship_designs is scoped to a single game, so every new match
-- started with an empty design library and players rebuilt the same
-- loadouts from scratch. These are USER-scoped: saved once, loadable
-- into any game's designer, and they follow the account across devices
-- (which is why this is a server table rather than localStorage).
--
-- Deliberately NOT a foreign key to game_ship_designs: a template is a
-- detached snapshot. Deleting the design (or the whole game) it was
-- saved from must never delete the template.
CREATE TABLE IF NOT EXISTS user_ship_templates (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  ship_class    TEXT NOT NULL,
  parts_json    TEXT,
  icon_variant  TEXT,
  created_at_ms INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_user_ship_templates_user
  ON user_ship_templates (user_id, ship_class, created_at_ms);
` },
  { name: "0039_default_ship_templates.sql", sql: `-- Seed a "Default" ship template per class for every EXISTING user.
-- New signups get theirs in handleSignup (worker/index.js); this covers
-- everyone who already had an account.
--
-- Ids are deterministic ('tpl_def_<user>_<class>') and each INSERT is
-- guarded by NOT EXISTS, so re-running is a no-op — important because
-- the migration runner may retry a partially-applied migration.
--
-- Loadouts KEEP IN SYNC with DEFAULT_LOADOUTS in worker/shipDesigns.js.
-- A user who edits or deletes their Default keeps that choice: the guard
-- only skips on (user, class, name='Default'), and a deleted one is not
-- resurrected because this migration runs exactly once.

INSERT INTO user_ship_templates (id, user_id, name, ship_class, parts_json, icon_variant, created_at_ms)
SELECT 'tpl_def_' || u.id || '_corvette', u.id, 'Default', 'corvette',
       '["weapon","engine"]', NULL, 0
  FROM users u
 WHERE NOT EXISTS (
   SELECT 1 FROM user_ship_templates t
    WHERE t.user_id = u.id AND t.ship_class = 'corvette' AND t.name = 'Default'
 );

INSERT INTO user_ship_templates (id, user_id, name, ship_class, parts_json, icon_variant, created_at_ms)
SELECT 'tpl_def_' || u.id || '_frigate', u.id, 'Default', 'frigate',
       '["weapon","weapon","shield","engine"]', NULL, 0
  FROM users u
 WHERE NOT EXISTS (
   SELECT 1 FROM user_ship_templates t
    WHERE t.user_id = u.id AND t.ship_class = 'frigate' AND t.name = 'Default'
 );

INSERT INTO user_ship_templates (id, user_id, name, ship_class, parts_json, icon_variant, created_at_ms)
SELECT 'tpl_def_' || u.id || '_destroyer', u.id, 'Default', 'destroyer',
       '["weapon","weapon","weapon","shield","shield","engine"]', NULL, 0
  FROM users u
 WHERE NOT EXISTS (
   SELECT 1 FROM user_ship_templates t
    WHERE t.user_id = u.id AND t.ship_class = 'destroyer' AND t.name = 'Default'
 );

INSERT INTO user_ship_templates (id, user_id, name, ship_class, parts_json, icon_variant, created_at_ms)
SELECT 'tpl_def_' || u.id || '_freighter', u.id, 'Default', 'freighter',
       '["engine"]', NULL, 0
  FROM users u
 WHERE NOT EXISTS (
   SELECT 1 FROM user_ship_templates t
    WHERE t.user_id = u.id AND t.ship_class = 'freighter' AND t.name = 'Default'
 );
` },
  { name: "0040_research_gating.sql", sql: `-- 0040_research_gating.sql
--
-- Research-gated feature rollout. Every mechanic beyond the starting kit
-- (1 corvette + 1 colony ship + your capital) now sits behind a research
-- level — see src/game/researchUnlocks.ts for the tree.
--
-- gating_enabled is the grandfather switch:
--   0  pre-existing games. Every feature stays unlocked regardless of
--      research, so a match already in progress is completely unaffected.
--      This is why the DEFAULT is 0 and why seedGameWorld sets it to 1
--      explicitly for new games rather than relying on the default.
--   1  new games. Features gate on research level.
--
-- Deliberately NOT a backfill of faction_techs: retroactively "granting"
-- live factions the levels matching what they've already built would be
-- guesswork, and any mistake silently removes a feature a player is
-- mid-way through using. A per-game switch is exact.

ALTER TABLE games ADD COLUMN gating_enabled INTEGER NOT NULL DEFAULT 0;
` },
  { name: "0041_trade_deliveries.sql", sql: `-- 0041_trade_deliveries.sql
--
-- Physical trade delivery. Accepting a trade no longer teleports
-- resources between faction pools — it creates one delivery row per
-- giving side, and the goods only move when a freighter physically
-- hauls them from one of the sender's collectors to one of the
-- recipient's collectors.
--
-- Lifecycle (driven by the room tick, pass 2d):
--   unassigned  no ship yet. The obligation exists; the sender is
--               prompted in the Trades panel to assign a freighter.
--   to_pickup   ship assigned, en route to (or sitting at) pickup_body.
--               Cargo NOT yet aboard — pool not yet debited.
--   outbound    loaded. Sender's pool was debited in the same tick the
--               ship sat at its collector; goods now ride the hull.
--   delivered   arrived at dest_body; recipient's pool credited (minus
--               the tariff snapshotted at accept).
--   lost        freighter destroyed with cargo aboard — the killer
--               looted the hold (mirrors trade-route piracy). If the
--               ship dies BEFORE loading, the row returns to
--               'unassigned' instead: nothing was aboard, the
--               obligation survives, assign another freighter.
--
-- Cargo amounts live HERE, not on game_ships — same pattern as
-- game_trade_routes.cargo_*: the mission row is the manifest.
--
-- tariff_pct is snapshotted at accept so a senate slider passed while
-- the freighter is mid-burn doesn't retroactively re-price a deal both
-- sides already agreed to.

CREATE TABLE IF NOT EXISTS trade_deliveries (
  id                   TEXT PRIMARY KEY,
  game_id              TEXT NOT NULL,
  trade_id             TEXT NOT NULL,
  sender_faction_id    TEXT NOT NULL,
  recipient_faction_id TEXT NOT NULL,
  ship_id              TEXT,              -- NULL until a freighter is assigned
  status               TEXT NOT NULL DEFAULT 'unassigned',
  pickup_body_id       TEXT,              -- sender collector chosen at assign
  dest_body_id         TEXT,              -- recipient collector chosen at assign
  metal                INTEGER NOT NULL DEFAULT 0,
  fuel                 INTEGER NOT NULL DEFAULT 0,
  gold                 INTEGER NOT NULL DEFAULT 0,
  science              INTEGER NOT NULL DEFAULT 0,
  loaded               INTEGER NOT NULL DEFAULT 0,  -- 1 = cargo aboard, pool debited
  tariff_pct           INTEGER NOT NULL DEFAULT 0,
  created_at_tick      INTEGER NOT NULL DEFAULT 0,
  resolved_at_tick     INTEGER
);

CREATE INDEX IF NOT EXISTS idx_trade_deliveries_game_active
  ON trade_deliveries (game_id) WHERE resolved_at_tick IS NULL;
CREATE INDEX IF NOT EXISTS idx_trade_deliveries_ship
  ON trade_deliveries (ship_id) WHERE ship_id IS NOT NULL;

-- Every capital city gets a collector, in EVERY game (live ones too —
-- physical delivery rolls out everywhere, so every faction needs at
-- least one place to load and one place to receive from day one).
-- Additional collectors stay behind Propulsion 4 exactly as before;
-- this only guarantees the floor.
UPDATE game_settlements
   SET has_collector = 1
 WHERE type = 'city'
   AND has_collector = 0
   AND EXISTS (
     SELECT 1 FROM game_factions f
      WHERE f.game_id = game_settlements.game_id
        AND f.id = game_settlements.owner_faction_id
        AND f.capital_body_id = game_settlements.body_id
   );
` },
  { name: "0042_scale_active_games_to_2x.sql", sql: `-- ============================================================================
-- Retroactively apply SYSTEM_SCALE = 2 to games seeded before the change.
--
-- Bodies are copied into game_bodies at seed time, so doubling the catalog
-- (worker/factions.js) only ever reached NEW games. This spreads the four
-- active 1x games out to match, so every running campaign plays on the same
-- board instead of the scale being an accident of start date.
--
-- WHAT MOVES
--   Heliocentric bodies only: orbit_radius x2, orbit_period x2^1.5, and the
--   eccentric Kuiper elements (orbit_rp/orbit_ra) x2 so they travel with the
--   orbit they describe. Exactly the transform factions.js applies to the
--   catalog, so a migrated game is indistinguishable from a fresh one.
--
-- WHAT DOESN'T
--   Moons: their orbits are parent-relative, so they ride along with their
--   planet untouched. angle0: every body keeps its current angle, so the
--   system expands in place rather than teleporting anyone to a new position
--   on its ring. soi: unscaled, matching what new games get.
--
-- SHIPS UNDER BURN
--   Server-side transit position is derived from LIVE body positions plus a
--   time fraction (worker/state.js), not a frozen trajectory, so nobody is
--   stranded by the bodies moving. But arrival_at_tick was solved for the OLD
--   distance, and leaving it would let in-flight hulls cross the new, larger
--   gap in the old time -- a free boost to whoever happened to be mid-transit.
--
--   So the remaining leg is stretched by sqrt(2): travel is T = 2*sqrt(d/a),
--   so doubling distance costs sqrt(2) time, not 2x.
--
--   Both ends are stretched around the CURRENT tick, not just the arrival.
--   Position renders as (tick - scheduled_t) / (arrival_at_tick - scheduled_t);
--   moving only the arrival grows that denominator, which would snap every
--   in-flight ship visibly BACKWARD along its path and rob players of progress
--   they had already flown. Scaling both ends about \`now\` holds that fraction
--   exactly where it is and lengthens only what's left.
--
-- IDEMPOTENT: targets are captured up front into a marker table keyed on the
-- 1x Earth radius (186). Re-running matches nothing, because by then Earth is
-- at 372. The marker table is also why the guard is captured BEFORE any
-- writes: a correlated guard would be re-read mid-UPDATE, against rows this
-- very statement is busy doubling.
-- ============================================================================

CREATE TABLE IF NOT EXISTS _scale2x_targets (game_id TEXT PRIMARY KEY);

INSERT OR IGNORE INTO _scale2x_targets (game_id)
SELECT b.game_id
FROM game_bodies b
WHERE b.template_id = 'earth'
  AND b.orbit_radius = 186;

-- 1) Heliocentric bodies. Parented to the game's own Sol row, so moons
--    (parented to their planet) are excluded by construction.
UPDATE game_bodies
SET orbit_radius = ROUND(orbit_radius * 2),
    orbit_period = ROUND(orbit_period * 2.8284271247461903),
    orbit_rp     = CASE WHEN orbit_rp IS NULL THEN NULL ELSE ROUND(orbit_rp * 2) END,
    orbit_ra     = CASE WHEN orbit_ra IS NULL THEN NULL ELSE ROUND(orbit_ra * 2) END
WHERE game_id IN (SELECT game_id FROM _scale2x_targets)
  AND parent_body_id IN (
    SELECT s.id FROM game_bodies s
    WHERE s.game_id = game_bodies.game_id
      AND s.template_id = 'sol'
  );

-- 2) In-flight transits: stretch both ends about the current tick by sqrt(2).
UPDATE game_ship_nodes
SET scheduled_t =
      (SELECT g.current_tick FROM games g
         JOIN game_ships s ON s.game_id = g.id
        WHERE s.id = game_ship_nodes.ship_id)
      - ((SELECT g.current_tick FROM games g
            JOIN game_ships s ON s.game_id = g.id
           WHERE s.id = game_ship_nodes.ship_id) - scheduled_t)
        * 1.4142135623730951,
    arrival_at_tick =
      (SELECT g.current_tick FROM games g
         JOIN game_ships s ON s.game_id = g.id
        WHERE s.id = game_ship_nodes.ship_id)
      + (arrival_at_tick
         - (SELECT g.current_tick FROM games g
              JOIN game_ships s ON s.game_id = g.id
             WHERE s.id = game_ship_nodes.ship_id))
        * 1.4142135623730951
WHERE target_body_id IS NOT NULL
  AND ship_id IN (
    SELECT s.id FROM game_ships s
    WHERE s.game_id IN (SELECT game_id FROM _scale2x_targets)
  )
  AND arrival_at_tick > (
    SELECT g.current_tick FROM games g
      JOIN game_ships s ON s.game_id = g.id
     WHERE s.id = game_ship_nodes.ship_id
  );

DROP TABLE _scale2x_targets;
` },
  { name: "0043_research_queue.sql", sql: `-- Research queue (MP): the next projects to auto-start once the current
-- one finishes, so players can line up a research path instead of
-- babysitting the tech panel every time a level completes.
--
-- research_queue is a JSON array of tech ids in FIFO order. The per-tick
-- research pass in worker/room.js promotes the head of this queue into
-- research_tech_id whenever research goes idle (a level just completed,
-- OR the player enqueued something while nothing was researching) —
-- skipping any maxed/unknown entries. Empty '[]' = no queue.
--
-- Additive with a constant DEFAULT, so every existing faction row
-- backfills to an empty queue — no behavior change until a player
-- actually queues something.
ALTER TABLE game_factions ADD COLUMN research_queue TEXT NOT NULL DEFAULT '[]';
` },
  { name: "0044_last_damaged_tick.sql", sql: `-- Battle-damage FX: when did this hull/settlement last TAKE damage?
-- Distinct from last_combat_tick (when it FIRED — that column gates the
-- return-fire cadence and must not be stamped on being hit; see the
-- warning in worker/state.js). The client renders persistent fire/smoke
-- on anything damaged within the last tick, so "damage was taken" reads
-- at a glance instead of relying on a split-second flash at the tick.
ALTER TABLE game_ships ADD COLUMN last_damaged_tick INTEGER;
ALTER TABLE game_settlements ADD COLUMN last_damaged_tick INTEGER;
` },
  { name: "0045_build_list.sql", sql: `-- Curated build list (ship builder redesign): an ordered set of loadout
-- entries the player has assigned to their build panel, so BUILD is a
-- pick from YOUR loadouts rather than one-active-design-per-class over a
-- fixed roster of every hull (including ones you can't build yet).
--
-- JSON array on the faction, global across every owned shipyard. Each
-- entry is either { "design_id": "<id>" } (a saved game_ship_designs row)
-- or { "bare_class": "corvette" } (a stock hull, no parts). NULL = the
-- player hasn't curated one yet; the client shows a sensible default
-- (unlocked bare hulls + active designs) until they do.
ALTER TABLE game_factions ADD COLUMN build_list_json TEXT;
` },
  { name: "0046_captains.sql", sql: `-- Captains (DESIGN-captains.md): a named, persistent officer attached to
-- every ship. Captains OWN veterancy (rank/combat_history move here); a
-- ship with no captain performs at rank 0. Backfill is lazy in the tick
-- pass (worker/captains.js ensureCaptains) — every active ship across
-- EVERY faction gets a captain minted inheriting the ship's rank, so no
-- live game loses veterancy and rival aces aren't stealth-nerfed.
CREATE TABLE IF NOT EXISTS game_captains (
  id               TEXT PRIMARY KEY,
  game_id          TEXT NOT NULL,
  faction_id       TEXT NOT NULL,
  name             TEXT NOT NULL,
  avatar_id        TEXT,                 -- code-shipped SVG id ('a1'..'a12')
  bio              TEXT,                 -- auto-generated, player-editable
  rank             INTEGER NOT NULL DEFAULT 0,
  combat_history   TEXT,                 -- JSON kill records (LRU, moved off ship)
  traits_json      TEXT,                 -- JSON array of trait ids
  ship_id          TEXT,                 -- NULL = in the bank, unassigned
  status           TEXT NOT NULL DEFAULT 'active',  -- active | lost
  created_at_tick  INTEGER NOT NULL DEFAULT 0,
  lost_at_tick     INTEGER
);
CREATE INDEX IF NOT EXISTS idx_captains_game_faction ON game_captains (game_id, faction_id);
CREATE INDEX IF NOT EXISTS idx_captains_ship ON game_captains (ship_id);

-- Ship -> captain pointer. game_ships.rank/combat_history become
-- read-only legacy after backfill (kept one release for rollback).
ALTER TABLE game_ships ADD COLUMN captain_id TEXT;
` },
  { name: "0047_ship_target.sql", sql: `-- Round-robin single-target combat: each combatant fires at ONE target
-- per volley (priority: armed ships → civilian ships → armed stations →
-- remaining settlements). The server records who each shooter is
-- currently engaging so the client's combat animation can aim its bolts
-- at the REAL target instead of a cosmetically-seeded guess.
ALTER TABLE game_ships ADD COLUMN last_target_id TEXT;
ALTER TABLE game_settlements ADD COLUMN last_target_id TEXT;
` },
  { name: "0048_tighter_park_orbits.sql", sql: `-- Tighter park orbits: ships now park at body radius + 2 (was +4), which
-- read as "twice the planet's disc away" and crowded moon lanes in busy
-- systems. New spawns/arrivals get the tight orbit from the code; this
-- pulls EXISTING parked fleets in too. Only ever shrinks (never widens a
-- tighter orbit), and skips ships whose parent body row is missing.
-- Transiting ships are included harmlessly — their orbit is rewritten on
-- arrival anyway.
UPDATE game_ships SET
  orbit_rp = (SELECT COALESCE(b.radius, 4) + 2 FROM game_bodies b WHERE b.id = game_ships.parent_body_id),
  orbit_ra = (SELECT COALESCE(b.radius, 4) + 2 FROM game_bodies b WHERE b.id = game_ships.parent_body_id)
WHERE status = 'active'
  AND EXISTS (SELECT 1 FROM game_bodies b WHERE b.id = game_ships.parent_body_id)
  AND orbit_rp > (SELECT COALESCE(b.radius, 4) + 2 FROM game_bodies b WHERE b.id = game_ships.parent_body_id);
` },
  { name: "0049_fleets.sql", sql: `-- ============================================================================
-- Fleets (DESIGN-fleets.md): ships grouped under a flag captain for common
-- orders. flag_captain_id NULL = leaderless (flagship lost; player must
-- promote a member captain before the fleet takes new common orders).
-- No FK on flag_captain_id by design — captains move to the bank / are lost
-- and the fleet row must survive that transition.
-- ============================================================================
CREATE TABLE IF NOT EXISTS game_fleets (
  id               TEXT PRIMARY KEY,
  game_id          TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  faction_id       TEXT NOT NULL,
  name             TEXT NOT NULL,
  flag_captain_id  TEXT,
  created_at_tick  INTEGER NOT NULL DEFAULT 0
);
ALTER TABLE game_ships ADD COLUMN fleet_id TEXT;
CREATE INDEX IF NOT EXISTS idx_ships_fleet ON game_ships(fleet_id);
CREATE INDEX IF NOT EXISTS idx_fleets_game ON game_fleets(game_id);
` },
  { name: "0050_reset_captains_to_ten.sql", sql: `-- ============================================================================
-- Captain reset: wipe the auto-mint era, start everyone at the 10-captain
-- allotment (2026-07-28, Lorne).
--
-- The old ensureCaptains minted a free captain for every hull, so live games
-- carry one captain per ship (46+ in the big game). With captains now a
-- finite resource (STARTING_CAPTAINS=10 + paid recruits), existing games
-- keep an inventory the new economy would never have produced.
--
-- This deletes EVERY captain and detaches them from ships and fleet flags.
-- On each game's next tick, ensureCaptainFloor re-rolls a fresh 10 per
-- faction and ensureCaptains assigns them to captainless COMBAT ships in
-- random order (bank-pull only). Every ship beyond those ten sails
-- uncommanded — by design: no trait, no rank growth, no fleet flag.
--
-- Cost accepted knowingly: captain rank/kill history from the free era is
-- erased. Ship-side legacy rank columns are untouched, so hull veterancy
-- survives where it was ever recorded.
-- ============================================================================

DELETE FROM game_captains;
UPDATE game_ships  SET captain_id = NULL WHERE captain_id IS NOT NULL;
UPDATE game_fleets SET flag_captain_id = NULL WHERE flag_captain_id IS NOT NULL;
` },
  { name: "0051_captain_bench.sql", sql: `-- ============================================================================
-- Explicit captain bench (2026-07-28, Lorne playtest).
--
-- ensureCaptains (worker/captains.js) runs every tick and posts the
-- longest-waiting bank captain onto any captainless same-faction ship,
-- preferring combat hulls, otherwise at random. That is the intended
-- distribution behavior for a NEW hull (0050's "bank-pull only" note) —
-- but it also silently undid a deliberate bench: with 10 captains and
-- 19+ ships there is always an orphan hull to soak one up, so "→ To the
-- bank" bounced the captain straight back onto a random ship within one
-- tick, and a swap re-posted the displaced captain somewhere arbitrary.
--
-- benched_at_tick records a PLAYER decision to hold a captain in reserve.
-- ensureCaptains skips those; assigning to a ship clears it. NULL means
-- "arrived in the bank on its own" (starting allotment, a fresh recruit,
-- or a rescue) and stays auto-assignable, preserving today's behavior for
-- every captain currently in a live game.
-- ============================================================================

ALTER TABLE game_captains ADD COLUMN benched_at_tick INTEGER;
` },
  { name: "0052_analytics.sql", sql: `-- ============================================================================
-- 0052: Admin analytics telemetry
--
-- Three additions, all write-cheap and read-rarely (only the admin
-- dashboard queries them):
--
-- 1. faction_metrics — one row per (game, tick, faction) recorded at the
--    end of resolveTick. This is the yield-curve source: game_factions
--    only holds CURRENT resources, so without a per-tick record there is
--    no history to chart. Rows are ~40 bytes; a 4000-tick 8-faction game
--    tops out around 32k rows, well inside D1 comfort.
--
-- 2. analytics_events — one row per mutating player action (POST/PATCH/
--    DELETE under /api/games/…), kind = normalized route ("ships/orders",
--    "fleets", "build-queue"…). Answers "which features get used".
--
-- 3. sessions.last_seen_at — touched (throttled to ~1/min) by the /state
--    poll, so (last_seen_at − created_at) approximates session length
--    and MAX(last_seen_at) gives true last-activity, which
--    users.last_login_at cannot (sessions live for weeks).
-- ============================================================================

CREATE TABLE faction_metrics (
  game_id      TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  tick_number  INTEGER NOT NULL,
  faction_id   TEXT NOT NULL,
  metal        INTEGER NOT NULL DEFAULT 0,
  fuel         INTEGER NOT NULL DEFAULT 0,
  gold         INTEGER NOT NULL DEFAULT 0,
  science      INTEGER NOT NULL DEFAULT 0,
  ships        INTEGER NOT NULL DEFAULT 0,
  settlements  INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (game_id, tick_number, faction_id)
);

CREATE TABLE analytics_events (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  game_id       TEXT,
  user_id       TEXT,
  kind          TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
);

CREATE INDEX idx_analytics_events_game ON analytics_events(game_id, created_at_ms);
CREATE INDEX idx_analytics_events_user ON analytics_events(user_id, created_at_ms);

ALTER TABLE sessions ADD COLUMN last_seen_at INTEGER;
` },
  { name: "0053_spend_events.sql", sql: `-- ============================================================================
-- 0053: Spend-by-category telemetry
--
-- The yield-flow chart shows NET resource movement; balancing prices needs
-- to know WHERE the spend goes (ships vs buildings vs colonies vs
-- captains). One row per debiting player action, written by logSpend()
-- alongside the existing debit batch. Income is not logged here - it is
-- already derivable from faction_metrics deltas plus this table.
-- ============================================================================

CREATE TABLE spend_events (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  game_id       TEXT NOT NULL,
  faction_id    TEXT,
  category      TEXT NOT NULL,       -- 'ships'|'buildings'|'colonies'|'captains'|...
  metal         INTEGER NOT NULL DEFAULT 0,
  gold          INTEGER NOT NULL DEFAULT 0,
  created_at_ms INTEGER NOT NULL
);

CREATE INDEX idx_spend_game ON spend_events(game_id, created_at_ms);
` },
  { name: "0054_fleet_upkeep_rush_refit.sql", sql: `-- ============================================================================
-- 0054 — Fleet economy: upkeep/arrears, rush construction, refit propagation
-- (DESIGN-fleet-economy §1 §2 §3)
-- ============================================================================
--
-- Upkeep (§1): every active hull bills per-tick maintenance (corvette 0.25c,
-- frigate 1c+1m, destroyer 2c+2m, freighter 1c). Faction pools are INTEGER,
-- so fractional bills accumulate in the carry columns until a whole unit is
-- due (same trick as 0028's yield remainders, in reverse). What a faction
-- CAN'T pay lands in the arrears columns; any positive arrears = the whole
-- fleet fights at 75% damage until the debt clears. Arrears never destroys
-- ships and repays automatically from the next tick's income.
ALTER TABLE game_factions ADD COLUMN upkeep_carry_gold  REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN upkeep_carry_metal REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN arrears_gold       REAL NOT NULL DEFAULT 0;
ALTER TABLE game_factions ADD COLUMN arrears_metal      REAL NOT NULL DEFAULT 0;

-- Rush (§3): pay the ship's full price again to halve REMAINING build time.
-- Unlimited rushes per order; each one carries a 25% chance the hull is
-- delivered at half health. The roll happens at rush time (server-side) and
-- is sticky — a botched order can't get worse, and can't be un-botched.
ALTER TABLE game_body_build_queue ADD COLUMN rush_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE game_body_build_queue ADD COLUMN botched    INTEGER NOT NULL DEFAULT 0;

-- Refit (§2): saving a template change can propagate to live hulls for a fee
-- (half the parts-price delta per ship). Ships at a friendly shipyard refit
-- immediately; everyone else carries the design id here and refits (and is
-- charged) on next arrival at a friendly yard — see the arrival pass hook.
ALTER TABLE game_ships ADD COLUMN refit_pending_design_id TEXT;
` },
  { name: "0054_perf_samples.sql", sql: `-- ============================================================================
-- 0054: Client performance samples
--
-- "The UI feels unresponsive" could not be reproduced from another
-- machine: two players in the SAME game (identical payload, identical
-- server) reported completely different responsiveness, so the cost is
-- client-side and only measurable on the client that has it.
--
-- One row per sampled player action (rate-limited client-side to at most
-- one per 30s per session), carrying the click -> painted-pixels
-- breakdown plus coarse device capability so slow reports can be
-- correlated with hardware instead of guessed at.
-- ============================================================================

CREATE TABLE perf_samples (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  game_id       TEXT,
  user_id       TEXT,
  total_ms      INTEGER NOT NULL,   -- action fired -> pixels painted
  action_ms     INTEGER NOT NULL,   -- POST round-trip
  fetch_ms      INTEGER NOT NULL,   -- /state round-trip
  map_ms        INTEGER NOT NULL,   -- JSON -> GameState (client CPU)
  paint_ms      INTEGER NOT NULL,   -- React commit + canvas redraw
  frame_ms      INTEGER NOT NULL,   -- rolling frame interval
  ships         INTEGER NOT NULL,   -- scene size at sample time
  cores         INTEGER,            -- navigator.hardwareConcurrency
  mem_gb        INTEGER,            -- navigator.deviceMemory (coarse, may be null)
  mobile        INTEGER,            -- 1 = touch/mobile UA
  ua            TEXT,               -- browser/OS string, for repro
  created_at_ms INTEGER NOT NULL
);

CREATE INDEX idx_perf_game ON perf_samples(game_id, created_at_ms);
CREATE INDEX idx_perf_user ON perf_samples(user_id, created_at_ms);
` },
  { name: "0055_perf_heartbeats.sql", sql: `-- ============================================================================
-- 0055: Session performance heartbeats
--
-- perf_samples (0054) measures ONE CLICK: action -> painted pixels. It says
-- nothing about how the animation feels between clicks, and it only fires
-- when a player acts — so a report of "animations are slowing down" is
-- invisible to it.
--
-- This table is the continuous view: one row per minute of active play per
-- client, carrying frame-rate distribution (not just an average — the 1%
-- low is what "choppy" actually means), the map's own draw cost, JS heap
-- size, scene complexity, and full device/GPU identity.
--
-- session_ms is the load-bearing column: charting fps against it answers
-- "does it get worse the longer you play", which is the difference between
-- a slow machine (flat line) and a leak (downward slope).
-- ============================================================================

CREATE TABLE perf_heartbeats (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  game_id        TEXT,
  user_id        TEXT,
  session_id     TEXT NOT NULL,      -- random per page load; groups a session
  session_ms     INTEGER NOT NULL,   -- ms since this client loaded the game

  -- Frame-rate distribution over the heartbeat window (visible frames only)
  fps_avg        INTEGER NOT NULL,
  fps_low1       INTEGER NOT NULL,   -- 1% low: the stutter a player feels
  frame_p50      INTEGER NOT NULL,
  frame_p95      INTEGER NOT NULL,
  long_frames    INTEGER NOT NULL,   -- frames over 50ms in the window
  frames_seen    INTEGER NOT NULL,

  -- Map render cost, measured inside the draw call itself
  draw_p50       INTEGER NOT NULL,
  draw_p95       INTEGER NOT NULL,

  -- Memory: a climbing heap across a session is the leak signature
  heap_mb        INTEGER,
  heap_limit_mb  INTEGER,

  -- Scene complexity, so cost can be normalized against what is on screen
  ships          INTEGER NOT NULL,
  settlements    INTEGER NOT NULL,
  in_transit     INTEGER NOT NULL,
  zoom           REAL,

  -- Device identity
  gpu            TEXT,
  cores          INTEGER,
  mem_gb         INTEGER,
  dpr            REAL,
  screen_w       INTEGER,
  screen_h       INTEGER,
  mobile         INTEGER,
  ua             TEXT,

  created_at_ms  INTEGER NOT NULL
);

CREATE INDEX idx_hb_game ON perf_heartbeats(game_id, created_at_ms);
CREATE INDEX idx_hb_session ON perf_heartbeats(session_id, session_ms);
` },
  { name: "0056_state_version.sql", sql: `-- ============================================================================
-- 0056: Monotonic per-game state version
--
-- /state assembly costs ~500ms in a 229-ship game (measured: ~15 D1
-- round-trips that barely parallelize), and it is the floor under every
-- click's response time. But between a tick and the next player action
-- the assembled payload is BYTE-IDENTICAL poll after poll (verified
-- live) - so cache it. The version bumps at the request choke point on
-- every mutating game action; the cache key is
-- (game, faction, state_version, current_tick), so ticks invalidate via
-- the tick number and actions via this counter. A spurious bump is a
-- harmless cache miss; a missed bump would be stale state, which is why
-- the bump lives at the dispatch choke point rather than in handlers.
-- ============================================================================

ALTER TABLE games ADD COLUMN state_version INTEGER NOT NULL DEFAULT 0;
` },
  { name: "0057_notifications.sql", sql: `-- ============================================================================
-- 0057: Discord DM notifications
--
-- Everything the bot did until now was BROADCAST — a digest, a vote card,
-- posted to a channel on a schedule. Nothing ever reached a specific
-- person. In a game where a tick is an hour, that is the whole engagement
-- problem: analytics show players 10 and 34 days idle who never decided
-- to quit, nothing simply pulled them back.
--
-- Two tables:
--
--   notification_prefs — per user, per category, on/off. Opt-OUT (absent
--     row = enabled) because a notification nobody asked for is the
--     entire point of a re-engagement ping. /notify turns them off.
--
--   notification_log — one row per delivered DM. Serves three jobs:
--     dedupe (never tell you twice about the same battle), rate limiting
--     (an idle nudge at most once a week), and honest measurement of
--     whether any of this actually brings people back.
-- ============================================================================

CREATE TABLE notification_prefs (
  user_id     TEXT NOT NULL,
  category    TEXT NOT NULL,      -- 'dm'|'combat'|'senate'|'economy'|'digest'|'nudge'
  enabled     INTEGER NOT NULL DEFAULT 1,
  updated_ms  INTEGER NOT NULL,
  PRIMARY KEY (user_id, category)
);

CREATE TABLE notification_log (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id     TEXT NOT NULL,
  game_id     TEXT,
  category    TEXT NOT NULL,
  -- Stable identity of the THING being reported (a message id, a battle
  -- at a body on a tick). The unique index below is what makes repeat
  -- delivery impossible rather than merely unlikely.
  dedupe_key  TEXT,
  ok          INTEGER NOT NULL DEFAULT 1,   -- 0 = send failed (DMs closed, etc)
  created_ms  INTEGER NOT NULL
);

CREATE UNIQUE INDEX idx_notif_dedupe ON notification_log(user_id, dedupe_key)
  WHERE dedupe_key IS NOT NULL;
CREATE INDEX idx_notif_user_time ON notification_log(user_id, created_ms);
` },
  { name: "0058_bot_settings.sql", sql: `-- ============================================================================
-- 0058: Bot settings
--
-- Everything the bot does was compile-time constant: the Herald's hour,
-- whether quiet situation reports send, which channel receives what.
-- Changing any of it meant a code edit and a deploy, which is a poor fit
-- for knobs whose right value is discovered by watching real players
-- react — "6pm not noon" is a preference, not an engineering decision.
--
-- Deliberately a key/value table rather than typed columns: the settings
-- list will churn as the bot grows, and a migration per knob would be
-- worse than parsing a few strings. Values are JSON so a setting can
-- become an object later without another migration.
-- ============================================================================

CREATE TABLE bot_settings (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,        -- JSON-encoded
  updated_ms  INTEGER NOT NULL,
  updated_by  TEXT                  -- user id, for an audit trail
);
` },
  { name: "0059_dm_consent.sql", sql: `-- ============================================================================
-- 0059: explicit consent before the bot DMs anyone
--
-- 0057 shipped DMs as opt-OUT: an absent prefs row meant enabled, so the
-- moment a player linked Discord the bot could DM them. That is the wrong
-- default for a direct message. Linking exists to let you VOTE from
-- Discord and to put your name on senate cards; plenty of players want
-- exactly that and nothing in their inbox. Reading a link as permission
-- to DM is us deciding on their behalf.
--
-- So: a master gate, asked once at link time, above the per-category
-- prefs. The categories stay opt-out and answer "which of these DMs do I
-- want"; this answers the prior question, "do I want DMs at all".
--
--   NULL — never asked. No DMs. The bot asks at the next opportunity.
--   1    — yes, DM me.
--   0    — server only. Senate cards, the Herald and slash commands all
--          still work; nothing lands in their inbox.
--
-- Channel posts are deliberately NOT gated by this. They are addressed to
-- the room, not the person, and a player who declines DMs has said
-- nothing about the shared channel.
--
-- Existing linked accounts are grandfathered to 1 in the backfill below.
-- They linked under the old rule and have been receiving DMs without
-- complaint; silently cutting them off would be a second wrong default
-- rather than a fix for the first. Everyone who links from here on is
-- asked.
-- ============================================================================

ALTER TABLE users ADD COLUMN dm_consent INTEGER;
ALTER TABLE users ADD COLUMN dm_consent_ms INTEGER;

-- dm_consent_ms = 0 marks "grandfathered", never explicitly asked.
UPDATE users
   SET dm_consent = 1,
       dm_consent_ms = 0
 WHERE discord_id IS NOT NULL
   AND dm_consent IS NULL;
` },
  { name: "0060_ungrandfather_dm_consent.sql", sql: `-- ============================================================================
-- 0060: un-grandfather the accounts 0059 let through
--
-- 0059 backfilled every already-linked account to dm_consent = 1 on the
-- reasoning that they had been receiving DMs without complaint. That
-- reasoning was wrong in the way that matters: nobody had ever ASKED
-- them. They linked under a rule where linking silently switched DMs on,
-- so "didn't complain" is not consent — it's the absence of a question.
--
-- The point of the whole feature is that some players want the server
-- posts and nothing in their inbox. Grandfathering was the one case where
-- that preference still could not surface. Lorne's call, and the right
-- one.
--
-- Effect: every grandfathered account goes back to NULL — unasked, and
-- therefore no DMs — until they answer. The ask is already waiting for
-- them in two places they will hit naturally: the in-game Notifications
-- panel renders it whenever consent is NULL, and /notify poses it
-- instead of listing categories.
--
-- The cost, accepted deliberately: a player who touches neither surface
-- simply stops receiving DMs and is never told why. Senate cards, the
-- Herald and slash commands still reach them in the channel, so nobody
-- is cut off from the game itself — only from their inbox, which is
-- exactly the thing they never agreed to.
--
-- Targeted by dm_consent_ms = 0, the marker 0059 wrote for precisely
-- this: "grandfathered, never explicitly asked". Anyone who has answered
-- since carries a real timestamp and is left alone.
-- ============================================================================

UPDATE users
   SET dm_consent = NULL,
       dm_consent_ms = NULL
 WHERE dm_consent_ms = 0;
` },
  { name: "0061_game_configs.sql", sql: `-- ============================================================================
-- 0061: editable game configuration — drafts, publishing, test games
--
-- Every balance number in Orbital has lived as a module-level const, which
-- means changing one has always required me: edit, build, deploy. That is
-- a bad loop for balance work, where the whole job is trying a value,
-- watching what happens, and trying another.
--
-- A config is a sparse JSON object of OVERRIDES over the schema defaults
-- in worker/configSchema.js. Sparse matters: a draft that only touches
-- mint_per_level stays one key wide, so a later change to any other
-- default flows through instead of being frozen at whatever it was the
-- day the draft was saved.
--
-- status:
--   'draft'     — editable, launchable as a test game, invisible to players
--   'published' — the config new games are created with
--   'archived'  — was published once; kept because games still point at it
--
-- GAMES PIN THEIR CONFIG. games.config_id is captured at creation and
-- never rewritten, so publishing a change cannot alter the rules of a
-- match already in progress. That was the explicit call: new games only.
-- It also means an archived config must survive forever — a running game
-- referencing a deleted row would fall back to defaults mid-match and
-- silently rebalance itself.
-- ============================================================================

CREATE TABLE game_configs (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'draft',   -- draft | published | archived
  -- Sparse overrides only. {} is a perfectly valid config meaning
  -- "everything as shipped".
  overrides     TEXT NOT NULL DEFAULT '{}',
  notes         TEXT,
  -- Where this draft came from, so the editor can show a lineage and diff
  -- against the thing it was branched from.
  parent_id     TEXT,
  created_by    TEXT,
  created_ms    INTEGER NOT NULL,
  updated_ms    INTEGER NOT NULL,
  published_ms  INTEGER
);

CREATE INDEX idx_configs_status ON game_configs(status, updated_ms DESC);

-- Nullable: every existing game keeps NULL and resolves to schema
-- defaults, which is exactly the behaviour it has today.
ALTER TABLE games ADD COLUMN config_id TEXT;

-- Marks a game launched from a draft for testing, so the lobby can badge
-- it and analytics can exclude it from real-player statistics.
ALTER TABLE games ADD COLUMN is_test_game INTEGER NOT NULL DEFAULT 0;
` },
  { name: "0062_combat_v2_restat.sql", sql: `-- 0062_combat_v2_restat.sql
--
-- COMBAT V2 (DESIGN-combat-v2.md). Ship stats are stamped at BUILD time, so
-- changing SHIP_COMBAT_STATS only affects hulls built from now on. Without
-- this migration two generations of ship would fight under one rule set and a
-- destroyer built yesterday would be permanently worse than one built
-- tomorrow. Lorne: "We'll need to migrate all existing ships."
--
-- Live at time of writing: 207 destroyers, 63 frigates, 19 corvettes,
-- 32 freighters, 4 colony ships.
--
-- The stat formula is unchanged — hp = base.hp * (1 + 0.35*defensive parts),
-- damage = base.damage * (1 + 0.40*mounts*tech) — so only the BASE moved and
-- every existing hull can be restated by a per-class constant. No need to
-- re-parse parts_json.
--
--   class       hp base        damage base        hp x     damage x
--   corvette    40 -> 40       5     -> 3.75      1.0      0.75
--   frigate     100 -> 100     10    -> 20.25     1.0      2.025
--   destroyer   200 -> 400     18    -> 45        2.0      2.5
--   freighter   60 -> 60       0     -> 0         1.0      1.0
--   colony      60 -> 60       0     -> 0         1.0      1.0
--
-- Only destroyers change HP. \`hp\` scales with \`hp_max\` so a hull at 50% stays
-- at 50% — a destroyer does not get healed for free, and does not suddenly
-- read as damaged either.
--
-- IDEMPOTENT. The runner (worker/index.js) skips applied migrations, but a
-- mid-migration failure returns 500 WITHOUT stamping, so a retry re-runs every
-- statement. Scaling twice would be silent and unrecoverable, so the guard is
-- structural: one UPDATE that sets the marker in the same statement it uses as
-- its WHERE clause. Re-running matches zero rows.

ALTER TABLE game_ships ADD COLUMN combat_v2 INTEGER NOT NULL DEFAULT 0;

UPDATE game_ships
   SET hp = ROUND(hp * CASE ship_class WHEN 'destroyer' THEN 2.0 ELSE 1.0 END, 1),
       hp_max = ROUND(hp_max * CASE ship_class WHEN 'destroyer' THEN 2.0 ELSE 1.0 END, 1),
       damage_per_tick = ROUND(damage_per_tick * CASE ship_class
                                 WHEN 'corvette'  THEN 0.75
                                 WHEN 'frigate'   THEN 2.025
                                 WHEN 'destroyer' THEN 2.5
                                 ELSE 1.0 END, 1),
       combat_v2 = 1
 WHERE combat_v2 = 0;
` },
  { name: "0062_orbital_shields.sql", sql: `-- ============================================================================
-- 0062: Orbital Shields — a regenerating second health bar for settlements
--
-- Ships have been able to bombard cities for a while and cities have had
-- exactly one answer: structure, which never comes back. A settlement that
-- lost a fight stayed lost, so the only real defence was a fleet parked on
-- top of it forever. Shields give a defender something that RECOVERS, which
-- turns a raid into a raid rather than an amputation.
--
-- The tech gate already existed — researchUnlocks.js has had
-- 'building.shields' (Armor 3, "Hardened Settlements") and the
-- BUILDING_FEATURE mapping pointing at it — with no building on the other
-- end. This is the other end.
--
-- Three columns rather than two:
--
--   shield_hp          current pool. Absorbs damage BEFORE structure.
--   shield_hp_max      derived from building level; stored so the tick
--                      does not have to parse buildings_json to clamp
--                      regen, and so the client gets it in /state for
--                      free.
--   shield_down_tick   when the pool last hit zero. Regen pauses for a
--                      grace period after a collapse, so a shield that
--                      just broke cannot immediately soak the next volley.
--                      NULL = never collapsed / already recovered.
--
-- Deliberately NOT backfilled to a positive value: existing settlements get
-- 0/0 and stay unshielded until someone builds the thing. Handing every
-- standing city a free shield would retroactively rewrite every siege
-- currently in progress, and there are cities under fire right now.
-- ============================================================================

ALTER TABLE game_settlements ADD COLUMN shield_hp REAL NOT NULL DEFAULT 0;
ALTER TABLE game_settlements ADD COLUMN shield_hp_max REAL NOT NULL DEFAULT 0;
ALTER TABLE game_settlements ADD COLUMN shield_down_tick INTEGER;
` },
  { name: "0063_combat_tally.sql", sql: `-- 0063_combat_tally.sql
--
-- COMBAT V2 telemetry. Everything the balance simulations measured was
-- computed from shot-level data — volleys fired, volleys landed, damage
-- dealt, broken down by attacker class against target class. The live game
-- records none of that: analytics is derived from chronicle_entries and
-- game_ships, which only ever see the OUTCOME (a ship died) and never the
-- exchange that produced it.
--
-- Without this table there is no way to answer the question the rework
-- actually raises: does a corvette really hit a destroyer 88.9% of the time
-- in a real game, or did the model lie?
--
-- Shape is deliberately a rolling TALLY, not an event log. One row per
-- (game, attacker class, target class) — at most 6x6 = 36 rows per game,
-- UPSERTed once per tick. An event log would be millions of rows a day for
-- a number nobody reads per-shot.
--
--   volleys  shots taken (a miss still costs a volley)
--   hits     shots that landed
--   damage   total damage dealt AFTER mitigation, so it is what the target
--            actually absorbed rather than what was theoretically fired
--   kills    targets whose HP crossed zero on a tick this attacker class
--            damaged. Approximate by design: damage resolves simultaneously,
--            so with two classes shooting one hull both are credited. Read
--            it as "was present at the kill", not "landed the killing blow".
--
-- 'attacker_class' carries 'station' for settlement return fire, and
-- 'target_class' carries 'settlement' for bombardment, so the matrix covers
-- every combatant the game has rather than only ships.

CREATE TABLE IF NOT EXISTS game_combat_tally (
  game_id        TEXT NOT NULL,
  attacker_class TEXT NOT NULL,
  target_class   TEXT NOT NULL,
  volleys        INTEGER NOT NULL DEFAULT 0,
  hits           INTEGER NOT NULL DEFAULT 0,
  damage         REAL    NOT NULL DEFAULT 0,
  kills          INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (game_id, attacker_class, target_class)
);

CREATE INDEX IF NOT EXISTS idx_combat_tally_game ON game_combat_tally(game_id);
` },
  { name: "0064_target_priority.sql", sql: `-- 0064_target_priority.sql
--
-- Player-set TARGET PRIORITY (combat v2 follow-up). The v2 targeting
-- default is peer targeting — engage whoever is closest to your own
-- speed, inside a fixed tier ladder (armed ships > civilians > armed
-- stations > soft settlements). That default stays. This column lets a
-- player OVERRIDE the ladder per ship with a ranked list of target
-- categories, set from the ship card or in bulk.
--
--   NULL          auto — peer targeting, tier ladder (today's behavior)
--   JSON array    ranked category keys, a permutation of:
--                 ["corvette","frigate","destroyer","civilian","settlement"]
--                 'civilian'   = freighters + colony ships
--                 'settlement' = stations + cities (armed stations first
--                                within the category, matching the ladder)
--
-- The combat loop walks the ranked list and engages the first category
-- with a valid hostile present; WITHIN a category the nearest-speed pick
-- is unchanged. Putting 'settlement' first is legal and deliberate — a
-- raider can bomb the port while its escort tanks the guns. Stance,
-- peace pacts, and defensive-aggressor gating all still apply before
-- priority is consulted.

ALTER TABLE game_ships ADD COLUMN target_priority TEXT;
` },
  { name: "0065_settlement_hp_restat.sql", sql: `-- 0065_settlement_hp_restat.sql
--
-- The settlement HP triple never reached the settlements that already
-- existed. city_base_hp 100 -> 300 and station_base_hp 60 -> 180 changed
-- the DEFAULTS in worker/configSchema.js, but hp/hp_max are stamped at
-- FOUNDING (worker/actions.js reads the config once and writes literals),
-- so only settlements founded after that deploy got the new numbers.
--
-- Live at time of writing, and exactly two cohorts — no drift to reason
-- about:
--
--   city     100  x54     <- legacy, restated here
--   city     300  x11     <- founded post-triple, untouched
--   station   60  x40     <- legacy, restated here   (Lorne's Thoth Station)
--   station  180  x16     <- founded post-triple, untouched
--
-- Lorne: "I thought we upgraded station health? It's still showing 60?
-- That's like two hits from a destroyer." It was — and at combat v2
-- damage it was worse than that (see the note at the bottom).
--
-- hp scales with hp_max by the same factor, so a settlement under
-- bombardment keeps its damage percentage. A half-wrecked station comes
-- out half-wrecked, not healed and not newly critical.
--
-- IDEMPOTENT, structurally: one UPDATE that sets the marker it uses as
-- its own WHERE clause, so a retry after a mid-migration 500 (which does
-- NOT stamp _migrations) matches zero rows. The cohort test is belt and
-- braces on top — an already-tripled row fails it regardless.
--
-- NOTE for whoever tunes this next: a stock combat v2 destroyer deals 45
-- damage per landed hit, and a well-fitted one was observed at 135/tick.
-- 180 HP is 4 stock hits but under 2 from a real destroyer. If stations
-- are still melting, this is a config change (station_base_hp), not
-- another migration -- the Editor writes it per game.

ALTER TABLE game_settlements ADD COLUMN hp_restat INTEGER NOT NULL DEFAULT 0;

UPDATE game_settlements
   SET hp_max = ROUND(hp_max * 3, 1),
       hp     = ROUND(hp * 3, 1),
       hp_restat = 1
 WHERE hp_restat = 0
   AND ((type = 'city'    AND hp_max <= 100)
     OR (type = 'station' AND hp_max <= 60));
` },
  { name: "0066_station_hp_400.sql", sql: `-- 0066_station_hp_400.sql
--
-- station_base_hp 180 -> 400 (Lorne), applied to LIVE stations.
--
-- 0065 had just finished restating the legacy 60-HP cohort up to 180,
-- which fixed the "upgrade never reached existing settlements" bug but
-- left the number itself too low for combat v2: a fitted destroyer was
-- observed dealing 135 damage per tick, so 180 was under two volleys.
-- 400 buys a defender three, and deliberately puts stations ABOVE cities
-- (300) — an orbital weapons platform should outlast a surface
-- settlement, which is the reverse of the old 5:3 city:station ratio.
--
-- Founding reads worker/configSchema.js (def bumped in the same commit),
-- so NEW stations arrive at 400. No game overrides station_base_hp — the
-- one config row in prod is a draft with the key absent — so the schema
-- default governs every match.
--
-- hp scales with hp_max so a station mid-bombardment keeps its damage
-- percentage. Computed against the OLD hp_max: SQLite evaluates every
-- RHS expression in an UPDATE against the original row, so reading
-- hp_max here is safe even though the same statement rewrites it.
--
-- IDEMPOTENT via the hp_restat marker 0065 introduced, bumped to 2. A
-- retry after a mid-migration 500 (which does not stamp _migrations)
-- matches zero rows. The hp_max guard is belt and braces: a station
-- already at 400 is out of scope regardless of its marker.

UPDATE game_settlements
   SET hp     = ROUND(hp * 400.0 / hp_max, 1),
       hp_max = 400,
       hp_restat = 2
 WHERE hp_restat < 2
   AND type = 'station'
   AND hp_max > 0
   AND hp_max <= 180;
` },
  { name: "0067_rogue_asteroids_2x_speed.sql", sql: `-- 0067_rogue_asteroids_2x_speed.sql
--
-- Rogue asteroids now orbit at 2x the speed of a planet at the same
-- distance (Lorne). worker/factions.js halves their catalogue periods so
-- NEW games seed fast; this brings the 48 rocks already in flight across
-- the 8 live games along with them.
--
-- Halving orbit_period doubles angular rate everywhere, because every
-- consumer derives motion from that one field: the client's bodyPosition,
-- the server's transfer-intercept solver (room.js), and the Kepler path
-- the eccentric Kuiper trio (Black Sky, Vagrant, Augustín) uses. Nothing
-- caches a derived angular velocity.
--
-- RELATIVE, not absolute: the seeder scales catalogue periods by ~2.83 on
-- insert, so live rows read 1485..18837 where the catalogue says
-- 525..6660. Dividing in place is correct whatever that factor is, and
-- also survives a body whose orbit was altered by a Trajectory Control
-- Thruster ram.
--
-- SCOPE is type = 'asteroid' — exactly the six rogues per game. The belt
-- rocks (Ceres, Vesta, Pallas, Hygiea, Juno) are type = 'dwarf' and keep
-- planet-normal speed; they're a stationary resource field, not a chase.
--
-- IDEMPOTENT via a marker column: re-running matches zero rows, so a
-- retry after a mid-migration 500 (which does NOT stamp _migrations)
-- can't halve a second time and leave the rocks at 4x.

ALTER TABLE game_bodies ADD COLUMN rogue_2x INTEGER NOT NULL DEFAULT 0;

UPDATE game_bodies
   SET orbit_period = orbit_period / 2.0,
       rogue_2x = 1
 WHERE rogue_2x = 0
   AND type = 'asteroid'
   AND orbit_period > 0;
` },
];
